  // ── Refund / cancel → Reward Ladder clawback ─────────────────────────────
  // Phase 1: only reverses purchase_threshold Reward Ladder grants tied to the
  // order id. Studio Credits pack refunds are Phase 2 (wholesale credit netting).
  app.post("/shopify/webhooks/refunds-create", async (req: Request, res: Response) => {
    try {
      const shop = req.headers["x-shopify-shop-domain"] as string;
      const body = req.body || {};
      const orderId = body.order_id || body.admin_graphql_api_order_id || body.order?.id;
      if (!verifyShopifyWebhookHmac(req)) {
        console.warn("[Shopify Refunds Create] invalid HMAC", { shop, orderId });
        return res.status(401).send("Unauthorized");
      }
      if (shop && orderId) {
        void clawbackPurchaseThresholdForOrder({
          shop,
          orderId: String(orderId),
          reason: "reward_clawback:refund",
          idempotencyKey: `clawback:order-refund:${orderId}`,
        }).then((r) => {
          if (r.clawedGrants > 0) {
            console.log(`[Shopify Refunds Create] clawed ${r.clawedGrants} purchase_threshold grant(s) for order ${orderId}`);
          }
        }).catch((err: any) => console.warn("[Shopify Refunds Create] clawback failed:", err?.message));

        // Creator ledger: accumulate refunded cents from this refund event.
        const refundCents = Array.isArray(body.transactions)
          ? body.transactions.reduce(
              (s: number, t: any) => s + Math.max(0, Math.round(Number(t.amount || 0) * 100)),
              0,
            )
          : Math.max(0, Math.round(Number(body.amount || 0) * 100));
        if (refundCents > 0) {
          void import("./creator-ledger")
            .then(({ addCreatorOrderRefund }) =>
              addCreatorOrderRefund({
                shop,
                orderId: String(orderId),
                additionalRefundCents: refundCents,
              }),
            )
            .then((r) => {
              if (r.updated > 0) {
                console.log("[Shopify Refunds Create] creator ledger updated", r);
              }
            })
            .catch((err: any) =>
              console.warn("[Shopify Refunds Create] creator ledger failed:", err?.message),
            );
        }

        void import("./creator-packs")
          .then(({ clawbackCreatorPacksForOrder }) =>
            clawbackCreatorPacksForOrder({ shop, orderId: String(orderId) }),
          )
          .then((r) => {
            if (r.clawed > 0) {
              console.log("[Shopify Refunds Create] creator packs clawed", r);
            }
          })
          .catch((err: any) =>
            console.warn("[Shopify Refunds Create] creator packs failed:", err?.message),
          );

        void import("./merchant-packs")
          .then(({ clawbackMerchantPacksForOrder }) =>
            clawbackMerchantPacksForOrder({ shop, orderId: String(orderId) }),
          )
          .then((r) => {
            if (r.clawed > 0) {
              console.log("[Shopify Refunds Create] merchant packs clawed", r);
            }
          })
          .catch((err: any) =>
            console.warn("[Shopify Refunds Create] merchant packs failed:", err?.message),
          );
      }
      return res.status(200).send("OK");
    } catch (error: any) {
      console.error("[Shopify Refunds Create] error:", error);
      return res.status(200).send("OK");
    }
  });

