  function resolveSharedDesignImageUrl(raw: string): string | null {
    let u = raw.trim();
    if (!u) return null;
    const embedded = Math.max(u.lastIndexOf("https://"), u.lastIndexOf("http://"));
    if (embedded > 0) u = u.slice(embedded);
    if (u.startsWith("data:image/")) return null;
    if (
      u.startsWith("/objects/") ||
      u.startsWith("/apps/appai/") ||
      u.startsWith("/api/")
    ) {
      const origin = (process.env.APP_URL || process.env.PUBLIC_APP_URL || "").replace(/\/$/, "");
      return origin ? `${origin}${u}` : u;
    }
    try {
      const parsed = new URL(u);
      const host = parsed.hostname.toLowerCase();
      if (host !== "localhost" && parsed.protocol !== "https:") return null;
      const exact = new Set(["storage.googleapis.com", "storage.cloud.google.com", "localhost"]);
      const suffixes = [".supabase.co", ".replit.app", ".up.railway.app"];
      if (exact.has(host) || suffixes.some((s) => host === s.slice(1) || host.endsWith(s))) {
        return parsed.toString();
      }
      for (const rawOrigin of [process.env.APP_URL, process.env.PUBLIC_APP_URL]) {
        if (!rawOrigin) continue;
        try {
          const originHost = new URL(
            String(rawOrigin).startsWith("http") ? rawOrigin : `https://${rawOrigin}`,
          ).hostname.toLowerCase();
          if (host === originHost) return parsed.toString();
        } catch {
          // ignore bad env origin
        }
      }
      return null;
    } catch {
      return null;
    }
  }

  // Create share link for a design (public endpoint for Shopify embed)
  app.post("/api/designs/share", async (req: Request, res: Response) => {
    try {
      const { 
        imageUrl: rawImageUrl,
        thumbnailUrl,
        prompt,
        stylePreset,
        size,
        frameColor,
        transformScale,
        transformX,
        transformY,
        productTypeId,
        shopDomain,
        productId,
        productHandle,
        customerId: rawOwnerCustomerId,
      } = req.body;

      if (!rawImageUrl || !prompt) {
        return res.status(400).json({ error: "Missing required fields" });
      }

      const imageUrl = resolveSharedDesignImageUrl(String(rawImageUrl));
      if (!imageUrl) {
        return res.status(400).json({ error: "Invalid image URL" });
      }

      // Generate unique share token
      const shareToken = crypto.randomBytes(16).toString("hex");
      
      // Set expiration to 30 days from now
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + 30);

      // Resolve the sharer's internal customer id (for the share_design Reward Ladder rung).
      // Accept either the internal UUID or a Shopify customer id; verify via bearer token when present.
      let ownerCustomerId: string | null = null;
      if (rawOwnerCustomerId && shopDomain && /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(String(shopDomain))) {
        const tokenIdentity = verifyStorefrontIdentityToken(req);
        const isInternalCustomer = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(rawOwnerCustomerId));
        const resolved = await resolveStorefrontCustomerIdentity({
          shop: String(shopDomain),
          customerId: tokenIdentity && tokenIdentity.shop === shopDomain ? tokenIdentity.customerId : (isInternalCustomer ? String(rawOwnerCustomerId) : null),
          shopifyCustomerId: isInternalCustomer ? null : String(rawOwnerCustomerId),
        }).catch(() => null);
        if (resolved) ownerCustomerId = resolved.id;
      }

      const sharedDesign = await storage.createSharedDesign({
        designId: null, // Nullable for unsaved designs
        shareToken,
        imageUrl,
        thumbnailUrl: thumbnailUrl || null,
        prompt,
        stylePreset: stylePreset || null,
        size: size || "default",
        frameColor: frameColor || "default",
        transformScale: Math.round(transformScale ?? 100),
        transformX: Math.round(transformX ?? 50),
        transformY: Math.round(transformY ?? 50),
        productTypeId: productTypeId || null,
        shopDomain: shopDomain || null,
        productId: productId || null,
        productHandle: productHandle || null,
        ownerCustomerId,
        expiresAt,
        viewCount: 0,
      });

      // Build share URL
      let shareUrl = "";
      if (shopDomain && productHandle) {
        // For Shopify embeds, return the merchant's product page URL with design ID
        shareUrl = `https://${shopDomain}/products/${productHandle}?sharedDesignId=${sharedDesign.id}`;
      } else {
        // For non-Shopify, use our embed design page
        shareUrl = `/embed/design?productTypeId=${productTypeId}&sharedDesignId=${sharedDesign.id}`;
      }

      res.json({ 
        sharedDesignId: sharedDesign.id,
        shareToken: sharedDesign.shareToken,
        shareUrl,
        expiresAt: sharedDesign.expiresAt,
      });
    } catch (error) {
      console.error("Error creating share link:", error);
      res.status(500).json({ error: "Failed to create share link" });
    }
  });

