  // Redeem coupon (customer endpoint)
  app.post("/api/coupons/redeem", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { code } = req.body;
      
      if (!code) {
        return res.status(400).json({ error: "Coupon code is required" });
      }

      const customer = await storage.getCustomerByUserId(userId);
      if (!customer) {
        return res.status(404).json({ error: "Customer not found" });
      }

      const coupon = await storage.getCouponByCode(code);
      if (!coupon) {
        return res.status(404).json({ error: "Invalid coupon code" });
      }

      if (!coupon.isActive) {
        return res.status(400).json({ error: "Coupon is no longer active" });
      }

      if (coupon.expiresAt && new Date() > coupon.expiresAt) {
        return res.status(400).json({ error: "Coupon has expired" });
      }

      if (coupon.maxUses != null && coupon.usedCount >= coupon.maxUses) {
        return res.status(400).json({ error: "Coupon has reached maximum uses" });
      }

      const unlimitedUses = coupon.maxUses == null;
      if (!unlimitedUses) {
        const redemption = await storage.getCouponRedemption(coupon.id, customer.id);
        if (redemption) {
          return res.status(400).json({ error: "You have already redeemed this coupon" });
        }
      }

      const installation = await resolveInstallationForMerchant(coupon.merchantId);
      if (installation) {
        const cover = await merchantCanCoverCouponUnits(installation, coupon.creditAmount);
        if (!cover.ok) {
          return res.status(402).json({
            error: "MERCHANT_QUOTA_EXHAUSTED",
            message: cover.message || "This shop cannot issue more coupon credits right now.",
          });
        }
        const consumed = await consumeMerchantCouponUnits(installation, coupon.creditAmount);
        if (!consumed.ok) {
          return res.status(402).json({
            error: "MERCHANT_QUOTA_EXHAUSTED",
            message: consumed.message || "This shop cannot issue more coupon credits right now.",
          });
        }
      }

      const ledgerResult = await storage.applyCreditLedgerEntry({
        customerId: customer.id,
        deltaCredits: coupon.creditAmount,
        reason: "coupon",
        idempotencyKey: unlimitedUses
          ? `coupon:${coupon.id}:${customer.id}:${crypto.randomUUID()}`
          : `coupon:${coupon.id}:${customer.id}`,
        externalRef: String(coupon.id),
        metadata: { code: coupon.code },
      });
      if (!ledgerResult.inserted) {
        return res.status(409).json({ error: "Coupon could not be applied. Please try again." });
      }

      await storage.createCouponRedemption({
        couponId: coupon.id,
        customerId: customer.id,
      });

      await storage.updateCoupon(coupon.id, {
        usedCount: coupon.usedCount + 1,
      });

      await storage.createCreditTransaction({
        customerId: customer.id,
        type: "coupon",
        amount: coupon.creditAmount,
        description: `Redeemed coupon: ${coupon.code}`,
      });

      res.json({
        success: true,
        creditsAdded: coupon.creditAmount,
        newBalance: ledgerResult.balance?.credits ?? customer.credits + coupon.creditAmount,
      });
    } catch (error) {
      console.error("Error redeeming coupon:", error);
      res.status(500).json({ error: "Failed to redeem coupon" });
    }
  });

