  // Fetch parsed variant options (sizes/colors) for import wizard
  app.get("/api/admin/printify/blueprints/:blueprintId/variants", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { blueprintId } = req.params;
      const { providerId } = req.query;
      const merchant = await storage.getMerchantByUserId(userId);
      const printifyToken = resolveCatalogPrintifyToken(merchant);

      if (!printifyToken) {
        return res.status(400).json({ error: "Printify API token not configured" });
      }

      // Get providers if no providerId specified
      if (!providerId) {
        return res.status(400).json({
          error: "providerId is required — each print provider has different variants, costs, and shipping.",
          code: "PROVIDER_REQUIRED",
        });
      }

      const actualProviderId = Number(providerId);
      if (!Number.isFinite(actualProviderId) || actualProviderId <= 0) {
        return res.status(400).json({ error: "Invalid providerId" });
      }

      // Full catalog (incl. fully OOS colors) so the import wizard lists White/Black etc.
      const dual = await fetchPrintifyProviderVariantsDual(
        blueprintId,
        actualProviderId,
        printifyToken,
      );
      const variants = Array.isArray(dual.variants) ? dual.variants : [];
      
      // Parse variants to extract sizes and colors (simplified version of import logic)
      const sizesMap = new Map<string, { id: string; name: string; width: number; height: number }>();
      const colorsMap = new Map<string, { id: string; name: string; hex: string }>();
      const combinations: { sizeId: string; colorId: string }[] = [];
      
      const apparelSizes = ["XXS", "XS", "S", "M", "L", "XL", "2XL", "3XL", "4XL", "5XL", "XXL", "XXXL"];
      const apparelSizesLower = apparelSizes.map(s => s.toLowerCase());
      const namedSizes = ["small", "medium", "large", "extra large", "king", "queen", "twin", "full", "one size"];
      
      const looksLikeSize = (str: string): boolean => {
        const lower = str.toLowerCase().trim();
        if (lower.match(/^\d+[""']?\s*[xX×]\s*\d+[""']?$/)) return true;
        if (apparelSizesLower.includes(lower)) return true;
        if (namedSizes.includes(lower)) return true;
        if (lower.match(/^\d+\s*oz$/i)) return true;
        if (lower.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i)) return true;
        if (lower.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i)) return true;
        if (lower.match(/^pixel\s+(\d|fold|pro)/i)) return true;
        if (lower.match(/^(youth|kid'?s?|toddler|infant|baby)\s/i)) return true;
        return false;
      };
      
      for (const variant of variants) {
        const title = variant.title || "";
        const options = variant.options || {};
        
        const normalizedTitle = title
          .replace(/[″″‶‴]/g, '"')
          .replace(/[′′‵]/g, "'")
          .replace(/[""]/g, '"')
          .replace(/['']/g, "'");
        
        let extractedSizeId = "";
        
        // Try dimensional sizes
        const dimMatch = normalizedTitle.match(/(\d+)[""']?\s*[xX×]\s*(\d+)[""']?/);
        if (dimMatch) {
          const width = parseInt(dimMatch[1]);
          const height = parseInt(dimMatch[2]);
          extractedSizeId = `${width}x${height}`;
          const sizeName = `${width}" x ${height}"`;
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeName, width, height });
          }
        }
        
        // Check options for size
        if (!extractedSizeId && (options.size || options.Size)) {
          const sizeVal = options.size || options.Size;
          extractedSizeId = normalizeApparelSizeId(sizeVal);
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeVal, width: 0, height: 0 });
          }
        }
        
        // Try title parts
        // Use " / " (space-slash-space) split to preserve combined model names like "iPhone 12/12 Pro".
        // Fall back to "/" split only if no " / " separator exists.
        if (!extractedSizeId && title && (title.includes(" / ") || title.includes("/"))) {
          const hasSeparator = title.includes(" / ");
          const parts = hasSeparator
            ? title.split(" / ").map((p: string) => p.trim())
            : title.split("/").map((p: string) => p.trim());
          for (const part of parts) {
            const volumeMatch = part.match(/^(\d+)\s*oz$/i);
            if (volumeMatch) {
              extractedSizeId = `${volumeMatch[1]}oz`;
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: `${volumeMatch[1]}oz`, width: 0, height: 0 });
              }
              break;
            }
            if (apparelSizesLower.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            // Named sizes (Small, Medium, Large, King, Queen, One Size, etc.)
            if (namedSizes.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            // Phone/device models (iPhone 14, Galaxy S23, Pixel 7, etc.)
            // Combined model names like "iPhone 12/12 Pro" are preserved as a single token
            // because we split on " / " above.
            if (part.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i) ||
                part.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i) ||
                part.match(/^pixel\s+(\d|fold|pro)/i) ||
                part.match(/^samsung\s+(galaxy|note)/i) ||
                part.match(/^oneplus\s+\d/i) ||
                part.match(/^for\s+(iphone|galaxy|pixel|samsung)/i)) {
              extractedSizeId = part.toLowerCase().replace(/\s+/g, '_');
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
          }
        }
        
        let colorName = "";
        try {
          colorName = extractPrintifyColorName(options, title) || "";
        } catch {
          colorName = "";
        }
        if (extractedSizeId) {
          try {
            combinations.push({
              sizeId: extractedSizeId,
              colorId: colorName ? slugPrintifyColorId(colorName) : "",
            });
          } catch {
            /* skip a bad combo — still return sizes/colours */
          }
        }

        if (colorName && !colorsMap.has(colorName.toLowerCase())) {
          const colorId = slugPrintifyColorId(colorName);
          // Comprehensive color hex lookup - Printify API doesn't provide hex codes
          const colorHexMap: Record<string, string> = {
            // Basic colors
            "black": "#1a1a1a", "white": "#f5f5f5", "red": "#C41E3A", "blue": "#2563EB",
            "navy": "#1B2838", "green": "#22C55E", "yellow": "#FACC15", "orange": "#F97316",
            "pink": "#EC4899", "purple": "#A855F7", "gray": "#9E9E9E", "grey": "#9E9E9E",
            "brown": "#795548", "beige": "#F5F5DC", "cream": "#FFFDD0", "tan": "#D2B48C",
            // Solid prefix variants
            "solid black": "#1a1a1a", "solid white": "#f5f5f5", "solid red": "#C41E3A",
            "solid blue": "#2563EB", "solid navy": "#1B2838", "solid green": "#22C55E",
            // Heather variants
            "heather grey": "#9CA3AF", "heather gray": "#9CA3AF", "dark heather": "#4B5563",
            "heather navy": "#374151", "heather blue": "#60A5FA", "heather red": "#F87171",
            "heather forest": "#166534", "heather purple": "#A855F7", "heather orange": "#FB923C",
            "heather green": "#6B8E6B", "heather yellow gold": "#D9A441",
            // Common apparel colors
            "arctic white": "#F8FAFC", "jet black": "#0a0a0a", "charcoal": "#36454F",
            "burgundy": "#800020", "maroon": "#800000", "cardinal": "#8C1D40", "cardinal red": "#C41E3A",
            "fire red": "#FF3131", "scarlet": "#FF2400", "coral": "#FF7F50",
            "hot pink": "#FF69B4", "baby pink": "#F4C2C2", "light pink": "#FFB6C1", "soft pink": "#F7B6C8",
            "magenta": "#FF00FF", "fuchsia": "#FF00FF", "rose": "#FF007F",
            "sky blue": "#87CEEB", "light blue": "#ADD8E6", "royal blue": "#4169E1",
            "navy blue": "#000080", "cobalt": "#0047AB", "steel blue": "#4682B4",
            "oxford navy": "#1C2541", "indigo": "#4B0082",
            "kelly green": "#4CBB17", "forest green": "#228B22", "military green": "#4B5320",
            "olive": "#808000", "sage": "#9DC183", "mint": "#98FF98", "lime": "#32CD32",
            "bottle green": "#006A4E", "dark green": "#006400", "emerald": "#50C878",
            "gold": "#FFD700", "mustard": "#FFDB58", "lemon": "#FFF44F",
            "light yellow": "#FFFFE0", "sun yellow": "#FFE81F", "canary": "#FFEF00",
            "orange crush": "#FF6600", "burnt orange": "#CC5500", "peach": "#FFCBA4",
            "rust": "#B7410E", "terracotta": "#E2725B", "pumpkin": "#FF7518",
            "lavender": "#E6E6FA", "violet": "#EE82EE", "plum": "#DDA0DD",
            "lilac": "#C8A2C8", "grape": "#6F2DA8", "eggplant": "#614051",
            "hot chocolate": "#4A2C2A", "chocolate": "#7B3F00", "coffee": "#6F4E37",
            "mocha": "#967969", "espresso": "#4E312D", "walnut": "#773F1A",
            "sand": "#C2B280", "khaki": "#C3B091", "taupe": "#483C32",
            "camel": "#C19A6B", "nude": "#E3BC9A", "champagne": "#F7E7CE", "heather sand dune": "#C8B99A",
            "silver": "#C0C0C0", "ash": "#B2BEB5", "slate": "#708090",
            "steel grey": "#71797E", "gunmetal": "#2A3439", "anthracite": "#293133",
            "teal": "#008080", "cyan": "#00FFFF", "aqua": "#00FFFF",
            "turquoise": "#40E0D0", "seafoam": "#93E9BE",
            "ivory": "#FFFFF0", "pearl": "#FDEEF4", "natural": "#FAF0E6",
            "oatmeal": "#D5C4A1", "ecru": "#C2B280",
            // Sport specific
            "athletic heather": "#B8B8B8", "sport grey": "#9E9E9E",
            "dark grey heather": "#4B4B4B", "ice grey": "#D3D3D3",
            "vintage black": "#2B2B2B", "vintage navy": "#2C3E50",
            "washed black": "#3D3D3D", "stonewash blue": "#5DADE2"
          };
          const { hex } = resolvePrintifyColorHex(colorName);
          colorsMap.set(colorName.toLowerCase(), { id: colorId, name: colorName, hex });
        }
      }

      res.json({
        sizes: Array.from(sizesMap.values()),
        colors: Array.from(colorsMap.values()),
        combinations,
      });
    } catch (error) {
      console.error("Error fetching variant options:", error);
      res.status(500).json({ error: "Failed to fetch variant options" });
    }
  });

  // Update variant selection for a product type
  app.patch("/api/admin/product-types/:id/variants", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const productTypeId = parseInt(req.params.id);
      const { selectedSizeIds, selectedColorIds } = req.body;
      
      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) {
        return res.status(404).json({ error: "Merchant not found" });
      }

      const productType = await storage.getProductType(productTypeId);
      if (!productType) {
        return res.status(404).json({ error: "Product type not found" });
      }

      // Verify merchant ownership
      if (productType.merchantId && productType.merchantId !== merchant.id) {
        return res.status(403).json({ error: "Not authorized to modify this product" });
      }

      // Count Printify-real combos from variantMap (sizes × colours overcounts
      // when a colour is not sold in every size — e.g. 9×13=117 but only 91 exist).
      let variantMap: Record<string, unknown> = {};
      try {
        variantMap = typeof productType.variantMap === "string"
          ? JSON.parse(productType.variantMap || "{}")
          : productType.variantMap || {};
      } catch {
        variantMap = {};
      }
      const sizeCount = Array.isArray(selectedSizeIds) ? selectedSizeIds.length : 0;
      const colorCount = Array.isArray(selectedColorIds) ? selectedColorIds.length : 0;
      const cartesian = sizeCount * (colorCount || 1);
      const mapCount = countActiveVariantMapKeys(variantMap, selectedSizeIds, selectedColorIds);
      const reported = Number((req.body as { variantCount?: unknown })?.variantCount);
      const totalVariants =
        mapCount > 0
          ? mapCount
          : Number.isFinite(reported) && reported > 0
            ? reported
            : cartesian;

      if (totalVariants > SHOPIFY_MAX_VARIANTS_PER_PRODUCT) {
        return res.status(400).json({
          error: "Too many variants",
          details: `Selected options would create ${totalVariants} variants. Maximum is ${SHOPIFY_MAX_VARIANTS_PER_PRODUCT}.`,
        });
      }

      const updated = await storage.updateProductType(productTypeId, {
        selectedSizeIds: JSON.stringify(selectedSizeIds || []),
        selectedColorIds: JSON.stringify(selectedColorIds || []),
      });

      res.json(updated);
    } catch (error) {
      console.error("Error updating variant selection:", error);
      res.status(500).json({ error: "Failed to update variant selection" });
    }
  });

  type PlaceholderImageOption = {
    url: string;
    label: string;
    position?: string;
    source?: "blueprint" | "provider" | "placeholder";
  };

  function extractPrintifyImageUrl(img: any): string | undefined {
    if (typeof img === "string") return img;
    if (img && typeof img === "object") return img.src || img.url;
    return undefined;
  }

  function addPlaceholderOption(
    list: PlaceholderImageOption[],
    seen: Set<string>,
    url: string | undefined,
    label: string,
    position?: string,
    source?: PlaceholderImageOption["source"],
  ) {
    if (!url || seen.has(url)) return;
    seen.add(url);
    list.push({ url, label, position, source });
  }

  async function fetchPrintifyPlaceholderOptions(
    apiToken: string,
    blueprintId: number,
    providerId: number,
  ): Promise<PlaceholderImageOption[]> {
    const images: PlaceholderImageOption[] = [];
    const seen = new Set<string>();
    const headers = {
      Authorization: `Bearer ${apiToken}`,
      "Content-Type": "application/json",
    };

    const blueprintResponse = await fetchWithRetry(
      `https://api.printify.com/v1/catalog/blueprints/${blueprintId}.json`,
      { headers },
      2,
      1000,
    );
    if (blueprintResponse.ok) {
      const blueprintData = await blueprintResponse.json();
      (blueprintData.images || []).forEach((img: any, index: number) => {
        addPlaceholderOption(images, seen, extractPrintifyImageUrl(img), `Catalog image ${index + 1}`, undefined, "blueprint");
      });
    }

    const providerResponse = await fetchWithRetry(
      `https://api.printify.com/v1/catalog/blueprints/${blueprintId}/print_providers/${providerId}.json`,
      { headers },
      2,
      1000,
    );
    if (providerResponse.ok) {
      const providerData = await providerResponse.json();
      addPlaceholderOption(images, seen, extractPrintifyImageUrl(providerData.image), "Provider image", undefined, "provider");
    }

    const variantsResponse = await fetchWithRetry(
      `https://api.printify.com/v1/catalog/blueprints/${blueprintId}/print_providers/${providerId}/variants.json`,
      { headers },
      2,
      1000,
    );
    if (variantsResponse.ok) {
      const variantsData = await variantsResponse.json();
      const variants = variantsData.variants || variantsData || [];
      const firstVariant = variants[0];
      const variantId = firstVariant?.variant_id || firstVariant?.id;
      if (variantId) {
        const placeholderResponse = await fetchWithRetry(
          `https://api.printify.com/v1/catalog/blueprints/${blueprintId}/print_providers/${providerId}/variants/${variantId}/placeholders.json`,
          { headers },
          2,
          1000,
        );
        if (placeholderResponse.ok) {
          const placeholderData = await placeholderResponse.json();
          const placeholders = placeholderData.placeholders || placeholderData || [];
          for (const placeholder of placeholders) {
            const position = String(placeholder.position || "placeholder");
            const placeholderImages = placeholder.images || [];
            placeholderImages.forEach((img: any, index: number) => {
              addPlaceholderOption(
                images,
                seen,
                extractPrintifyImageUrl(img),
                `${position.replace(/_/g, " ")}${placeholderImages.length > 1 ? ` ${index + 1}` : ""}`,
                position,
                "placeholder",
              );
            });
          }
        }
      }
    }

    return images;
  }

  function buildBaseMockupImagesFromOptions(
    available: PlaceholderImageOption[],
    primaryUrl?: string,
    galleryUrls?: string[],
    customUrls?: string[],
  ) {
    const byPosition = (name: string) =>
      available.find((img) => (img.position || "").toLowerCase() === name || (img.position || "").toLowerCase().includes(name))?.url;
    const firstUrl = available[0]?.url;
    const detectedFront = byPosition("front") || firstUrl;
    const front = primaryUrl || detectedFront;
    const lifestyle = available.find((img) => img.source === "blueprint" && img.url !== front)?.url || available.find((img) => img.url !== front)?.url;
    const uniqueGallery = Array.from(new Set((galleryUrls || []).filter(Boolean))).slice(0, 4);
    const uniqueCustom = Array.from(new Set((customUrls || []).filter(Boolean))).slice(0, 4);
    return {
      ...(front ? { front } : {}),
      ...(lifestyle ? { lifestyle } : {}),
      ...(front ? { primary: front } : {}),
      gallery: uniqueGallery.length > 0 ? uniqueGallery : (front ? [front] : []),
      custom: uniqueCustom,
      available,
    };
  }

  /** Apply merchant placeholder picks from the customizer editor — clears stale lifestyle/custom. */
  function applyCuratedPlaceholderSelection(
    currentImages: Record<string, unknown>,
    incoming: { primary?: string; gallery?: string[]; custom?: string[] },
  ): Record<string, unknown> {
    const available = Array.isArray(currentImages.available) ? currentImages.available : [];
    const gallery = Array.isArray(incoming.gallery)
      ? incoming.gallery.map(String).filter(Boolean).slice(0, 4)
      : [];
    const primary =
      typeof incoming.primary === "string" && incoming.primary
        ? incoming.primary
        : String(currentImages.primary || currentImages.front || "");

    const incomingCustom = Array.isArray(incoming.custom)
      ? incoming.custom.map(String).filter(Boolean)
      : [];
    const selected = new Set([primary, ...gallery].filter(Boolean));
    const custom = incomingCustom.filter((url) => selected.has(url)).slice(0, 4);

    const next: Record<string, unknown> = {
      ...currentImages,
      ...(primary ? { primary, front: primary } : { primary: undefined, front: undefined }),
      gallery,
      custom,
      available,
    };
    delete next.lifestyle;
    // Preserve size-keyed catalog blanks (comforter / wall decals).
    if (
      currentImages.blanksBySize &&
      typeof currentImages.blanksBySize === "object" &&
      !Array.isArray(currentImages.blanksBySize)
    ) {
      next.blanksBySize = currentImages.blanksBySize;
    }
    return next;
  }

  function mergeCatalogSizeBlanksIfNeeded(
    blueprintId: number | null | undefined,
    images: Record<string, any>,
  ): Record<string, any> {
    if (!isCatalogSizeBlankBlueprint(blueprintId)) return images;
    const blanks = resolveCatalogSizeBlankUrlMap(blueprintId, getSupabaseDesignPublicUrl);
    if (!blanks) return images;
    return applyCatalogSizeBlanks(images, blanks) as Record<string, any>;
  }

  // GET available placeholder images before importing a Printify product.
  app.get("/api/admin/printify/blueprints/:blueprintId/providers/:providerId/placeholders", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) return res.status(404).json({ error: "Merchant not found" });
      const printifyToken = resolveCatalogPrintifyToken(merchant);
      if (!printifyToken) return res.status(400).json({ error: "Printify API token not configured" });

      const blueprintId = parseInt(req.params.blueprintId);
      const providerId = parseInt(req.params.providerId);
      if (!blueprintId || !providerId) return res.status(400).json({ error: "Invalid blueprint or provider ID" });

      const images = await fetchPrintifyPlaceholderOptions(printifyToken, blueprintId, providerId);
      res.json({ images });
    } catch (error) {
      console.error("Error fetching Printify placeholder images:", error);
      res.status(500).json({ error: "Failed to fetch placeholder images" });
    }
  });

  // Import a Printify blueprint as a product type
  /**
   * Core Printify blueprint import logic — shared by the merchant-driven
   * Products admin import AND the setup-rail "activate from platform
   * catalogue" flow (which supplies a platform Printify token instead of
   * requiring the merchant's own token — see opts.printifyTokenOverride).
   *
   * `req`/`res` only need `.user.claims.sub` / `.body` and `.status().json()`
   * respectively, so the setup-rail route can pass lightweight shims.
   */
  async function handlePrintifyImportRequest(
    req: any,
    res: any,
    opts?: { printifyTokenOverride?: string; autoCapVariants?: boolean },
  ) {
    try {
      const userId = req.user.claims.sub;
      const { blueprintId, name, description, providerId: bodyProviderId, selectedSizeIds, selectedColorIds, placeholderPrimaryUrl, placeholderGalleryUrls, customPlaceholderUrls } = req.body;
      const merchant = await storage.getMerchantByUserId(userId);
      
      if (!merchant) {
        return res.status(404).json({ error: "Merchant not found" });
      }

      const printifyToken =
        opts?.printifyTokenOverride || resolveCatalogPrintifyToken(merchant);
      if (!printifyToken) {
        return res.status(400).json({
          error: "Printify API token not configured",
          message: "Add a Printify API token in Settings, or set PRINTIFY_API_TOKEN on the server.",
        });
      }

      if (!blueprintId || !name) {
        return res.status(400).json({ error: "Blueprint ID and name are required" });
      }

      const blueprintIdNum = parseInt(blueprintId, 10);
      // Create Page / import often omit description — filled from Printify blueprint JSON below.
      let resolvedDescription = typeof description === "string" ? description.trim() : "";

      const catalogEntry = await getPlatformCatalogEntry(blueprintIdNum);
      const isOperator = isPlatformAdminRequest(req);

      if (!catalogEntry || catalogEntry.kind === "blocked") {
        return res.status(403).json({
          error: "This product is not available in the AI Art Studio catalog yet.",
          code: "BLUEPRINT_NOT_ALLOWED",
        });
      }

      if (isOperator) {
        if (!(await canOperatorImportEntry(catalogEntry))) {
          return res.status(403).json({ error: "Blueprint not allowed", code: "BLUEPRINT_NOT_ALLOWED" });
        }
      } else if (!(await canMerchantImportEntry(catalogEntry))) {
        if (catalogEntry.kind === "flat" || catalogEntry.kind === "aop") {
          return res.status(403).json({
            error: "Platform calibration for this product is not published yet.",
            code: "CANONICAL_NOT_PUBLISHED",
          });
        }
        return res.status(403).json({
          error: "This product is not available in the AI Art Studio catalog yet.",
          code: "BLUEPRINT_NOT_ALLOWED",
        });
      }

      let canonicalFlatMeta: CanonicalPublishedMeta | null = null;
      let canonicalManifest: Awaited<ReturnType<typeof resolveCanonicalFlatCalibration>>["manifest"] = null;
      if (catalogEntry.kind === "flat") {
        const resolved = await resolveCanonicalFlatCalibration(blueprintIdNum, {
          allowUnpublishedHarvest: isOperator,
        });
        canonicalFlatMeta = resolved.meta;
        canonicalManifest = resolved.manifest;
        if (!isOperator && catalogEntry.status === "published" && !canonicalManifest) {
          return res.status(403).json({
            error: "Platform calibration for this product is not published yet.",
            code: "CANONICAL_NOT_PUBLISHED",
          });
        }
      }

      // Fetch print providers for this blueprint with retry logic
      const providersResponse = await fetchWithRetry(
        `https://api.printify.com/v1/catalog/blueprints/${blueprintId}/print_providers.json`,
        {
          headers: {
            "Authorization": `Bearer ${printifyToken}`,
            "Content-Type": "application/json"
          }
        },
        3,
        1500
      );

      if (!providersResponse.ok) {
        throw new Error(`Failed to fetch providers: ${providersResponse.status}`);
      }

      const providers = await providersResponse.json();
      if (!providers || providers.length === 0) {
        return res.status(400).json({ error: "No print providers available for this blueprint" });
      }

      if (!bodyProviderId) {
        return res.status(400).json({
          error: "Print provider is required. Each supplier has different colours, production costs, and shipping.",
          code: "PROVIDER_REQUIRED",
        });
      }

      const providerId = Number(bodyProviderId);
      if (!Number.isFinite(providerId) || providerId <= 0) {
        return res.status(400).json({ error: "Invalid print provider ID" });
      }

      const providerValid = providers.some((p: { id: number }) => Number(p.id) === providerId);
      if (!providerValid) {
        return res.status(400).json({
          error: "Selected print provider is not available for this blueprint.",
          code: "PROVIDER_INVALID",
        });
      }

      // Unique on blueprint + provider (matches Products Import UI: re-import the same
      // blueprint with a different supplier for a separate EU/US listing).
      const existingTypes = await storage.getProductTypesByMerchant(merchant.id);
      const alreadyImported = existingTypes.find(
        (pt) =>
          pt.printifyBlueprintId === blueprintIdNum &&
          Number(pt.printifyProviderId) === providerId,
      );
      if (alreadyImported) {
        // Backfill description if Create Page / earlier import left it empty.
        if (!String(alreadyImported.description || "").trim()) {
          const fetched = await fetchPrintifyBlueprintDescriptionHtml(printifyToken, blueprintIdNum);
          if (fetched) {
            try {
              await storage.updateProductType(alreadyImported.id, { description: fetched });
            } catch (e: any) {
              console.warn("[printify-import] description backfill failed:", e?.message ?? e);
            }
          }
        }
        const providerTitle =
          (providers as Array<{ id: number; title?: string }>).find((p) => Number(p.id) === providerId)?.title ||
          `provider #${providerId}`;
        return res.status(400).json({
          error: `This product is already in your catalog as "${alreadyImported.name}" via ${providerTitle}. Open Products to edit it, or delete it there before importing again. To list the same blueprint with a different supplier, pick that supplier instead.`,
          code: "BLUEPRINT_ALREADY_IMPORTED",
          existingProductTypeId: alreadyImported.id,
          existingProductName: alreadyImported.name,
          existingProviderId: alreadyImported.printifyProviderId,
        });
      }

      // Fetch blueprint details to get color hex codes from options
      const blueprintResponse = await fetchWithRetry(
        `https://api.printify.com/v1/catalog/blueprints/${blueprintId}.json`,
        {
          headers: {
            "Authorization": `Bearer ${printifyToken}`,
            "Content-Type": "application/json"
          }
        },
        3,
        1500
      );

      let blueprintColors: Record<string, string> = {}; // colorName -> hex
      let blueprintColorOptionName: string | null = null; // Actual option name from Printify (e.g. "Material", "Fabric", "Color")
      if (blueprintResponse.ok) {
        const blueprintData = await blueprintResponse.json();
        if (!resolvedDescription) {
          const rawDesc = typeof blueprintData?.description === "string" ? blueprintData.description.trim() : "";
          if (rawDesc) resolvedDescription = sanitizeDesignProductDescriptionHtml(rawDesc);
        }
        // Extract the non-size option from blueprint options
        // First try color-type options, then fall back to any non-size option
        const colorOptions = blueprintData.options?.find((opt: any) => 
          opt.type === 'color' || opt.name?.toLowerCase() === 'color' || opt.name?.toLowerCase() === 'colors'
        );
        if (!colorOptions) {
          // No explicit color option — look for any option that isn't "size"
          const nonSizeOption = (blueprintData.options || []).find((opt: any) => {
            const name = (opt.name || '').toLowerCase();
            return name !== 'size' && name !== 'sizes' && opt.type !== 'size';
          });
          if (nonSizeOption) {
            blueprintColorOptionName = nonSizeOption.name || null;
            console.log(`Blueprint non-size option found: "${blueprintColorOptionName}" (type: ${nonSizeOption.type})`);
            // Extract values from this option for hex mapping if available
            if (nonSizeOption.values) {
              for (const val of nonSizeOption.values) {
                const valName = (val.title || val.name || '').toLowerCase();
                if (val.colors && val.colors.length > 0) {
                  blueprintColors[valName] = val.colors[0];
                } else if (val.hex_code) {
                  blueprintColors[valName] = val.hex_code;
                } else if (val.value && val.value.startsWith('#')) {
                  blueprintColors[valName] = val.value;
                }
              }
            }
          }
        } else {
          blueprintColorOptionName = colorOptions.name || 'Color';
        }
        if (colorOptions?.values) {
          for (const colorVal of colorOptions.values) {
            const colorName = (colorVal.title || colorVal.name || '').toLowerCase();
            // Prefer colors array with hex, or hex_code field, or try to extract from value
            if (colorVal.colors && colorVal.colors.length > 0) {
              blueprintColors[colorName] = colorVal.colors[0];
            } else if (colorVal.hex_code) {
              blueprintColors[colorName] = colorVal.hex_code;
            } else if (colorVal.value && colorVal.value.startsWith('#')) {
              blueprintColors[colorName] = colorVal.value;
            }
          }
        }
        console.log(`Extracted ${Object.keys(blueprintColors).length} colors from blueprint options:`, Object.keys(blueprintColors).slice(0, 5).join(', '), '...');
      } else {
        console.log(`Blueprint options API - color extraction: no color options found or options missing`);
      }

      // Dual-fetch: full catalog (show-out-of-stock=1) builds variantMap so fully OOS
      // colors like White/Black at JAMS still enter the denominator for stock scans.
      const dualCatalog = await fetchPrintifyProviderVariantsDual(
        blueprintId,
        providerId,
        printifyToken,
        {
          fetchFn: (url, init) => fetchWithRetry(String(url), init || {}, 3, 1500),
        },
      );
      const variantsData = dualCatalog.payload;
      const variants = dualCatalog.variants;
      if (!dualCatalog.usedFullCatalog) {
        console.warn(
          `[Import] Blueprint ${blueprintId} provider ${providerId}: full catalog fetch failed — using in-stock-only list (${variants.length} variants)`,
        );
      }
      // Extract flat-lay SVG images from the `views` field of the variants response.
      // views[] contains { position, label, files[{ src, variant_ids }] } — one entry per
      // print panel position. We build a map of position → SVG URL for the Place on Item viewer.
      const panelFlatLayImages: Record<string, string> = {};
      const views: Array<{ id?: number; label?: string; position: string; files: Array<{ src: string; variant_ids?: number[] }> }> =
        variantsData.views || [];
      for (const view of views) {
        if (view.position && view.files && view.files.length > 0 && view.files[0].src) {
          panelFlatLayImages[view.position] = view.files[0].src;
        }
      }
      // Static fallback: hard-coded SVG IDs for known blueprints where the Printify API
      // returns an empty `views` array. SVGs are served from the Printify public CDN.
      // Identified by loading the Printify editor and intercepting network requests.
      const STATIC_FLAT_LAY_SVGS: Record<number, Record<string, string>> = {
              // Complete Printify panel SVG mapping (auto-generated from Printify catalog)
              // Women's Cut & Sew Racerback Dress
              276: {
                "back"                : "https://images.printify.com/api/catalog/59fc4d34b8e7e30175347441.svg",
                "front"               : "https://images.printify.com/api/catalog/59fc4d2bb8e7e301856c6fa9.svg",
              },
              // Women's Cut & Sew Casual Leggings (AOP) — omitted; handled client-side
              // via STATIC_FLAT_LAY_FALLBACK in embed-design.tsx using /api/storefront/aop-mask
              // Unisex Cut & Sew Tee
              281: {
                "back"                : "https://images.printify.com/api/catalog/5a01d4b4b8e7e32813350528.svg",
                "front"               : "https://images.printify.com/api/catalog/5a01d4ceb8e7e3281f2da8e7.svg",
              },
              // Women's Pencil Skirt
              285: {
                "back"                : "https://images.printify.com/api/catalog/5a0ef125b8e7e307bc4e601c.svg",
                "front"               : "https://images.printify.com/api/catalog/5a0ef133b8e7e3087c7ebf08.svg",
              },
              // Unisex Sweatshirt
              449: {
                "back"                : "https://images.printify.com/api/catalog/5d9c87f418831d27426218b0.svg",
                "front"               : "https://images.printify.com/api/catalog/5d9b4bc1a54cf735a33aa246.svg",
                "left_sleeve"         : "https://images.printify.com/api/catalog/5d9b5255e577547f153b80dc.svg",
                "right_sleeve"        : "https://images.printify.com/api/catalog/5d9b35ebd41cb4389d15e043.svg",
              },
              // Unisex Pullover Hoodie
              450: {
                "back"                : "https://images.printify.com/api/catalog/5d971e0a2947a61bef6f40cd.svg",
                "front"               : "https://images.printify.com/api/catalog/5d96fefa40e8da18a2274ad9.svg",
                "left_sleeve"         : "https://images.printify.com/api/catalog/5d971d7ad69994742d3a03fb.svg",
                "right_sleeve"        : "https://images.printify.com/api/catalog/5d971dfcc4c83a05fc3a5492.svg",
              },
              // Unisex Zip Hoodie
              451: {
                "back"                : "https://images.printify.com/api/catalog/5d9ae61ccf4e077eb561b028.svg",
                "front_left"          : "https://images.printify.com/api/catalog/5d9c8b82c92a2a02ac3662dd.svg",
                "front_right"         : "https://images.printify.com/api/catalog/631b2116174f5066ca0759d4.svg",
                "left_cuff_panel"     : "https://images.printify.com/api/catalog/5d9ae385cf4e077eb561b01c.svg",
                "left_hood"           : "https://images.printify.com/api/catalog/5d9ae1fa4e699c71a202db06.svg",
                "left_sleeve"         : "https://images.printify.com/api/catalog/5d9ae1b44e699c71a202db03.svg",
                "pocket_left"         : "https://images.printify.com/api/catalog/5d9c8e67c92a2a02ac3662e0.svg",
                "pocket_right"        : "https://images.printify.com/api/catalog/5d9c8e76c92a2a02ac3662e3.svg",
                "right_cuff_panel"    : "https://images.printify.com/api/catalog/5d9c8335c92a2a02ac3662d4.svg",
                "right_hood"          : "https://images.printify.com/api/catalog/5d9ae1e932345a5ce56f1e1c.svg",
                "right_sleeve"        : "https://images.printify.com/api/catalog/5d9ae1d58bb77340c7729745.svg",
                "waistband"           : "https://images.printify.com/api/catalog/5d9b0eda32345a5ce56f1e37.svg",
              },
              // Crop Tee
              627: {
                "back"                : "https://images.printify.com/api/catalog/612e2dbdce911f74dc7fc430.svg",
                "front"               : "https://images.printify.com/api/catalog/61165b745cbffb455d742be8.svg",
              },
              // Women's Capri Leggings
              1050: {
                "left_leg"            : "https://images.printify.com/api/catalog/627268e348bb29a669061ca2.svg",
                "right_leg"           : "https://images.printify.com/api/catalog/627268d3ae9e71e7850a0ff1.svg",
              },
              // Tote Bag
              1389: {
                "front"               : "https://images.printify.com/api/catalog/6564848e6a2aafb6fe0ba0d3.svg",
              },
              // Men's Hawaiian Camp Shirt
              1533: {
                "back"                : "https://images.printify.com/api/catalog/66a21741405a59f9070d94c2.svg",
                "front_left"          : "https://images.printify.com/api/catalog/66a21c3817e48cae5b0ddbe2.svg",
                "front_right"         : "https://images.printify.com/api/catalog/66a21bb8f38ac84cd908f752.svg",
                "left_placket"        : "https://images.printify.com/api/catalog/69a6e89c7c21676d1f0bf552.svg",
                "right_placket"       : "https://images.printify.com/api/catalog/69a6e8695763f46f33003910.svg",
              },
              // Basketball Training Shorts
              1589: {
                "back_left_leg"       : "https://images.printify.com/api/catalog/66d70a472e7c84cf240029e6.svg",
                "back_right_leg"      : "https://images.printify.com/api/catalog/66d70a16650830a5b305c264.svg",
                "front_left_leg"      : "https://images.printify.com/api/catalog/66d709cd7438963da401ba55.svg",
                "front_right_leg"     : "https://images.printify.com/api/catalog/66d709486f43297fff0ce8a5.svg",
                "left_inner_pocket_back": "https://images.printify.com/api/catalog/66d70a44f835b084520c4364.svg",
                "left_inner_pocket_front": "https://images.printify.com/api/catalog/66d70a13febb2981ab02c692.svg",
                "right_inner_pocket_back": "https://images.printify.com/api/catalog/66d70a07c810c0506505ba93.svg",
                "right_inner_pocket_front": "https://images.printify.com/api/catalog/66d70a39619c41921c006035.svg",
              },
              // Unisex Polo Shirt
              1604: {
                "back"                : "https://images.printify.com/api/catalog/66e45967b94b48b3b80449f2.svg",
                "front"               : "https://images.printify.com/api/catalog/66e459529ec5cf39800ccb42.svg",
                "left_sleeve"         : "https://images.printify.com/api/catalog/66e4597bb94b48b3b80449f3.svg",
                "placket"             : "https://images.printify.com/api/catalog/66e459946fc58997a50cf387.svg",
                "right_sleeve"        : "https://images.printify.com/api/catalog/66e459726fc58997a50cf384.svg",
              },
              // Pixel Fleece Blanket
              1911: {
                "front"               : "https://images.printify.com/api/catalog/67b745ed32ecb119d80897c9.svg",
              },
            };
      if (Object.keys(panelFlatLayImages).length === 0) {
        const staticSvgs = STATIC_FLAT_LAY_SVGS[parseInt(blueprintId)];
        if (staticSvgs) {
          Object.assign(panelFlatLayImages, staticSvgs);
          console.log(`[Import] Using static flat-lay SVG mapping for blueprint ${blueprintId}: ${Object.keys(staticSvgs).join(", ")}`);
        }
      }
      console.log(`[Import] Extracted ${Object.keys(panelFlatLayImages).length} flat-lay images from views:`, Object.keys(panelFlatLayImages).join(", "));

      // Parse variants to extract sizes and colors
      // Sizes are purely catalog metadata - variant info goes in variantMap
      const sizesMap = new Map<string, { id: string; name: string; width: number; height: number }>();
      const colorsMap = new Map<string, { id: string; name: string; hex: string }>();
      // Map of "sizeId:colorId" -> printifyVariantId for accurate mockup generation
      const variantMap: Record<string, { printifyVariantId: number; providerId: number }> = {};
      let maxWidth = 0;
      let maxHeight = 0;
      
      // Track print area dimensions in pixels from Printify placeholders by position
      // These are used ONLY for aspect ratio calculation, not storage
      // Store per-position to handle multi-placement products correctly
      const placeholderDimensions: Record<string, { width: number; height: number }> = {};

      // Per-size placeholder dimensions: keyed by sizeId -> primary-position dims
      // Populated after extractedSizeId is known for each variant
      const placeholderDimensionsBySize: Record<string, { width: number; height: number }> = {};

      // Known size patterns for various product types
      const apparelSizes = ["XXS", "XS", "S", "M", "L", "XL", "2XL", "3XL", "4XL", "5XL", "XXL", "XXXL"];
      const apparelSizesLower = apparelSizes.map(s => s.toLowerCase());
      const namedSizes = ["small", "medium", "large", "extra large", "king", "queen", "twin", "full", "one size"];
      
      // Helper function to check if a string looks like a size (not a color)
      const looksLikeSize = (str: string): boolean => {
        const lower = str.toLowerCase().trim();
        // Dimensional (8x10, 12"x16")
        if (lower.match(/^\d+[""']?\s*[xX×]\s*\d+[""']?$/)) return true;
        // Apparel sizes (S, M, L, XL, 2XL)
        if (apparelSizesLower.includes(lower)) return true;
        // Named sizes (Small, Medium, Large, King, Queen)
        if (namedSizes.includes(lower)) return true;
        // Volume sizes (11oz, 15 oz)
        if (lower.match(/^\d+\s*oz$/i)) return true;
        // Device models - must have model identifier after brand
        // Don't match just "Galaxy" as it could be a color name like "Galaxy Blue"
        // iPhone: iPhone 14, iPhone X, iPhone XS, iPhone SE, iPhone Pro Max, etc.
        if (lower.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i)) return true;
        // Galaxy: Galaxy S23, Galaxy A54, Galaxy Note, Galaxy Z Fold/Flip, etc.
        if (lower.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i)) return true;
        // Pixel: Pixel 7, Pixel Fold, Pixel Pro, etc.
        if (lower.match(/^pixel\s+(\d|fold|pro)/i)) return true;
        // Samsung with model identifiers
        if (lower.match(/^samsung\s+(galaxy|note)/i)) return true;
        // OnePlus with model numbers
        if (lower.match(/^oneplus\s+\d/i)) return true;
        // Generic "for iPhone/Galaxy/etc" patterns often seen in case listings
        if (lower.match(/^for\s+(iphone|galaxy|pixel|samsung)/i)) return true;
        // Youth/Kids sizes
        if (lower.match(/^(youth|kid'?s?|toddler|infant|baby)\s/i)) return true;
        // Size with numbers (14x14, 50x60, etc for blankets/pillows)
        if (lower.match(/^\d+\s*["'']?\s*[xX×]\s*\d+/)) return true;
        return false;
      };
      
      for (const variant of variants) {
        const title = variant.title || "";
        const options = variant.options || {};
        
        // Extract print area dimensions from placeholders (if available)
        // Printify API returns placeholders[].width/height in pixels
        // Track dimensions per position (front, back, wrap, etc.) across all variants
        const placeholders = variant.placeholders || [];
        for (const placeholder of placeholders) {
          if (placeholder.width && placeholder.height) {
            const position = placeholder.position || "default";
            const existing = placeholderDimensions[position];
            // Keep the largest dimensions for each position across variants
            if (!existing || placeholder.width * placeholder.height > existing.width * existing.height) {
              placeholderDimensions[position] = { 
                width: placeholder.width, 
                height: placeholder.height 
              };
            }
          }
        }
        
        // Normalize Unicode quotes/primes to standard characters
        const normalizedTitle = title
          .replace(/[″″‶‴]/g, '"')
          .replace(/[′′‵]/g, "'")
          .replace(/[""]/g, '"')
          .replace(/['']/g, "'");
        
        // Track the extracted sizeId for this variant (used for variantMap)
        let extractedSizeId = "";
        
        // 1. Try dimensional sizes (8x10, 12"x16", etc.) for prints, pillows, blankets
        const dimMatch = normalizedTitle.match(/(\d+)[""']?\s*[xX×]\s*(\d+)[""']?/);
        if (dimMatch) {
          const width = parseInt(dimMatch[1]);
          const height = parseInt(dimMatch[2]);
          extractedSizeId = `${width}x${height}`;
          const sizeName = `${width}" x ${height}"`;
          
          // Sizes are purely catalog metadata - no variant-specific fields
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeName, width, height });
          }
          if (width > maxWidth) maxWidth = width;
          if (height > maxHeight) maxHeight = height;
        }
        
        // 2. Check options for size (normalize various key names)
        if (!extractedSizeId && (options.size || options.Size)) {
          const sizeVal = options.size || options.Size;
          extractedSizeId = normalizeApparelSizeId(sizeVal);
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeVal, width: 0, height: 0 });
          }
        }
        
        // 3. Try to extract from title for other patterns
        if (!extractedSizeId && title) {
          // Printify uses " / " (space-slash-space) as the separator between size and color/option.
          // Combined phone model names like "iPhone 12/12 Pro" use a bare "/" without spaces.
          // So splitting on " / " correctly preserves combined model names as a single token.
          // Fall back to "/" split only if no " / " separator exists (e.g. "8x10" alone).
          const hasSeparator = title.includes(" / ");
          const parts = hasSeparator
            ? title.split(" / ").map((p: string) => p.trim())
            : title.split("/").map((p: string) => p.trim());
          
          for (const part of parts) {
            // Check for volume sizes (11oz, 15oz for mugs)
            const volumeMatch = part.match(/^(\d+)\s*oz$/i);
            if (volumeMatch) {
              extractedSizeId = `${volumeMatch[1]}oz`;
              const sizeName = `${volumeMatch[1]}oz`;
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeName, width: 0, height: 0 });
              }
              break;
            }
            
            // Check apparel sizes (S, M, L, XL, 2XL, etc.)
            if (apparelSizesLower.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            
            // Check named sizes (Small, Medium, Large, King, Queen)
            if (namedSizes.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            
            // Check youth/kids sizes
            if (part.match(/^(youth|kid'?s?|toddler|infant|baby)\s/i)) {
              extractedSizeId = part.toLowerCase().replace(/\s+/g, '_').replace(/'/g, '');
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            
            // Check device models (iPhone 14, Galaxy S23, etc. for phone cases)
            // Must have model identifier to avoid matching colors like "Galaxy Blue"
            if (part.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i) || 
                part.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i) || 
                part.match(/^pixel\s+(\d|fold|pro)/i) ||
                part.match(/^samsung\s+(galaxy|note)/i) ||
                part.match(/^oneplus\s+\d/i) ||
                part.match(/^for\s+(iphone|galaxy|pixel|samsung)/i)) {
              extractedSizeId = part.toLowerCase().replace(/\s+/g, '_');
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
          }
        }
        
        // 4. Fallback: If still no size and title has parts, use first non-color part
        if (!extractedSizeId && title && title.includes("/")) {
          const parts = title.split("/").map((p: string) => p.trim());
          // Take the first part as size if it's not obviously a color
          const firstPart = parts[0];
          if (firstPart && !firstPart.match(/^(black|white|red|blue|green|yellow|pink|purple|orange|gray|grey|navy|brown|beige|cream|tan)/i)) {
            extractedSizeId = firstPart.toLowerCase().replace(/\s+/g, '_');
            if (!sizesMap.has(extractedSizeId)) {
              sizesMap.set(extractedSizeId, { id: extractedSizeId, name: firstPart, width: 0, height: 0 });
            }
          }
        }

        // Track per-size placeholder dimensions now that extractedSizeId is known.
        // Use the same primary-position priority (front > default > first available).
        if (extractedSizeId) {
          const variantPlaceholders: Record<string, { width: number; height: number }> = {};
          for (const ph of (variant.placeholders || [])) {
            if (ph.width && ph.height) {
              const pos = ph.position || "default";
              const ex = variantPlaceholders[pos];
              if (!ex || ph.width * ph.height > ex.width * ex.height) {
                variantPlaceholders[pos] = { width: ph.width, height: ph.height };
              }
            }
          }
          const primaryDims = pickPrimaryPrintPlaceholderDims(variantPlaceholders);
          if (primaryDims) {
            const existing = placeholderDimensionsBySize[extractedSizeId];
            // Keep the largest area seen for this size across variants
            if (!existing || primaryDims.width * primaryDims.height > existing.width * existing.height) {
              placeholderDimensionsBySize[extractedSizeId] = primaryDims;
            }
          }
        }

        const colorName = extractPrintifyColorName(options, title, blueprintColorOptionName);

        // Extract color and track the extractedColorId for this variant
        let extractedColorId = "";
        if (colorName) {
          extractedColorId = slugPrintifyColorId(colorName);
          
          if (!colorsMap.has(colorName.toLowerCase())) {
            // Map common color names to hex values (frames + apparel)
            // Normalize "Solid X" pattern by extracting base color name
            const baseColorName = colorName.toLowerCase()
              .replace(/^solid\s+/i, '')
              .replace(/^heather\s+/i, 'heather ')
              .trim();
            
            const colorHexMap: Record<string, string> = {
              // Basic colors
              "black": "#1a1a1a", "white": "#f5f5f5", "red": "#C41E3A", "blue": "#2563EB",
              "navy": "#1B2838", "green": "#22C55E", "yellow": "#FACC15", "orange": "#F97316",
              "pink": "#EC4899", "purple": "#A855F7", "gray": "#9E9E9E", "grey": "#9E9E9E",
              "brown": "#795548", "beige": "#F5F5DC", "cream": "#FFFDD0", "tan": "#D2B48C",
              // Frame colors
              "walnut": "#5D4037", "natural": "#D7CCC8", "gold": "#FFD700", "silver": "#C0C0C0",
              "oak": "#C4A35A", "cherry": "#9B2335", "mahogany": "#4E2728", "espresso": "#3C2415",
              // Heather variants
              "heather grey": "#9CA3AF", "heather gray": "#9CA3AF", "dark heather": "#4B5563",
              "heather navy": "#374151", "heather blue": "#60A5FA", "heather red": "#F87171",
              "heather forest": "#166534", "heather purple": "#A855F7", "heather orange": "#FB923C",
              "heather green": "#6B8E6B", "heather yellow gold": "#D9A441",
              // Common apparel colors
              "arctic white": "#F8FAFC", "jet black": "#0a0a0a", "charcoal": "#36454F",
              "burgundy": "#800020", "maroon": "#800000", "cardinal": "#8C1D40", "cardinal red": "#C41E3A",
              "fire red": "#FF3131", "scarlet": "#FF2400", "coral": "#FF7F50",
              "hot pink": "#FF69B4", "baby pink": "#F4C2C2", "light pink": "#FFB6C1", "soft pink": "#F7B6C8",
              "magenta": "#FF00FF", "fuchsia": "#FF00FF", "rose": "#FF007F",
              "sky blue": "#87CEEB", "light blue": "#ADD8E6", "royal blue": "#4169E1",
              "royal": "#4169E1", "navy blue": "#000080", "cobalt": "#0047AB", "steel blue": "#4682B4",
              "oxford navy": "#1C2541", "indigo": "#4B0082", "midnight navy": "#191970",
              "cool blue": "#4A90D9", "tahiti blue": "#3AB09E",
              "kelly green": "#4CBB17", "forest green": "#228B22", "military green": "#4B5320",
              "olive": "#808000", "sage": "#9DC183", "mint": "#98FF98", "lime": "#32CD32",
              "bottle green": "#006A4E", "dark green": "#006400", "emerald": "#50C878",
              "mustard": "#FFDB58", "lemon": "#FFF44F", "banana cream": "#FFE9A1",
              "light yellow": "#FFFFE0", "sun yellow": "#FFE81F", "canary": "#FFEF00",
              "orange crush": "#FF6600", "burnt orange": "#CC5500", "peach": "#FFCBA4",
              "rust": "#B7410E", "terracotta": "#E2725B", "pumpkin": "#FF7518",
              "lavender": "#E6E6FA", "violet": "#EE82EE", "plum": "#DDA0DD",
              "lilac": "#C8A2C8", "grape": "#6F2DA8", "eggplant": "#614051", "purple rush": "#9B59B6",
              "hot chocolate": "#4A2C2A", "chocolate": "#7B3F00", "coffee": "#6F4E37",
              "mocha": "#967969", "dark chocolate": "#3D2314",
              "sand": "#C2B280", "khaki": "#C3B091", "taupe": "#483C32",
              "camel": "#C19A6B", "nude": "#E3BC9A", "champagne": "#F7E7CE", "desert pink": "#EDC9AF",
              "heather sand dune": "#C8B99A",
              "ash": "#B2BEB5", "slate": "#708090",
              "steel grey": "#71797E", "gunmetal": "#2A3439", "anthracite": "#293133",
              "light grey": "#D3D3D3", "light gray": "#D3D3D3", "heavy metal": "#3D3D3D",
              "teal": "#008080", "cyan": "#00FFFF", "aqua": "#00FFFF",
              "turquoise": "#40E0D0", "seafoam": "#93E9BE",
              "ivory": "#FFFFF0", "pearl": "#FDEEF4", "oatmeal": "#D5C4A1", "ecru": "#C2B280",
              // Sport specific
              "athletic heather": "#B8B8B8", "sport grey": "#9E9E9E",
              "dark grey heather": "#4B4B4B", "ice grey": "#D3D3D3",
              "vintage black": "#2B2B2B", "vintage navy": "#2C3E50",
              "washed black": "#3D3D3D", "stonewash blue": "#5DADE2"
            };
            
            const { hex, source } = resolvePrintifyColorHex(colorName, blueprintColors);
            if (source === "fallback") {
              console.log(`Color not found in resolver: "${colorName}" (normalized: "${baseColorName}")`);
            }
            colorsMap.set(colorName.toLowerCase(), { 
              id: extractedColorId, 
              name: colorName, 
              hex 
            });
          }
        }

        // Store the size+color -> variant mapping for mockup generation
        // Use the extractedSizeId and extractedColorId captured during this iteration
        // Only add to variantMap if we have at least a size or color - no fallback keys
        if (extractedSizeId || extractedColorId) {
          const mapKey = variantMapKey(extractedSizeId || "default", extractedColorId || "default");
          variantMap[mapKey] = { printifyVariantId: variant.id, providerId };
        } else {
          // Neither size nor color could be extracted - skip this variant for mockup generation
          // This ensures we never send the wrong variant to Printify
          console.warn(`Skipping variant for mockup mapping - could not extract size or color: ${title} (id: ${variant.id})`);
        }
      }

      // Convert maps to arrays
      let sizes = Array.from(sizesMap.values());
      const frameColors = Array.from(colorsMap.values());

      // Detect apparel before per-size aspect ratio (sizes.map uses isApparelProduct).
      const lowerName = name.toLowerCase();
      const lowerDesc = (description || "").toLowerCase();
      const combined = `${lowerName} ${lowerDesc}`;
      const matchesWord = (text: string, word: string): boolean => {
        const regex = new RegExp(`\\b${word}\\b`, 'i');
        return regex.test(text);
      };
      const apparelKeywords = [
        "shirt", "t-shirt", "tshirt", "hoodie", "sweatshirt", "tank top",
        "tee", "apparel", "jersey", "jacket", "leggings", "shorts",
        "dress", "skirt", "polo", "onesie", "bodysuit", "sweater",
        "pants", "joggers", "romper", "blouse", "cardigan", "vest",
        "coat", "bikini", "swimsuit", "underwear", "boxers", "briefs",
        "socks", "apron", "scrubs"
      ];
      const isApparelProduct = apparelKeywords.some(kw => matchesWord(combined, kw));

      sizes = sizes.map(s => {
        const dims = placeholderDimensionsBySize[s.id];
        if (dims) {
          let w = dims.width;
          let h = dims.height;
          if (isApparelProduct && w > h) [w, h] = [h, w];
          const ar = computeAspectRatioFromPixelDims(w, h);
          console.log(`[Import] Per-size aspect ratio: sizeId=${s.id} pxDims=${dims.width}x${dims.height} → ${ar}`);
          return { ...s, aspectRatio: ar };
        }
        return s;
      });

      // Fallback: If no sizes extracted, create from product name or use default
      // This handles single-variant products and products where size wasn't parseable
      if (sizes.length === 0) {
        // Try to extract size from product name (e.g., "Tumbler 20oz" -> "20oz")
        const sizeFromName = name.match(/(\d+\s*oz)/i);
        const defaultSizeId = sizeFromName ? sizeFromName[1].toLowerCase().replace(/\s+/g, '') : "default";
        const defaultSizeName = sizeFromName ? sizeFromName[1] : "One Size";
        sizes = [{ id: defaultSizeId, name: defaultSizeName, width: 0, height: 0 }];
        console.log(`[Import] Created fallback size "${defaultSizeName}" (id: ${defaultSizeId})`);

        // Update variantMap keys if we extracted a size from name
        if (defaultSizeId !== "default") {
          for (const key of Object.keys(variantMap)) {
            if (key.startsWith("default:")) {
              const colorId = key.slice(8); // "default:" is 8 chars
              const newKey = `${defaultSizeId}:${colorId}`;
              variantMap[newKey] = variantMap[key];
              delete variantMap[key];
            }
          }
        }

        // For single-variant products with no variantMap entries, create one
        if (Object.keys(variantMap).length === 0 && variants.length > 0) {
          const variantKey = `${defaultSizeId}:default`;
          variantMap[variantKey] = { printifyVariantId: variants[0].id, providerId };
          console.log(`[Import] Created fallback variantMap entry: ${variantKey}`);
        }
      }

      let availablePlaceholderImages: PlaceholderImageOption[] = [];
      try {
        availablePlaceholderImages = await fetchPrintifyPlaceholderOptions(
          printifyToken,
          parseInt(blueprintId),
          providerId,
        );
        console.log(`Fetched ${availablePlaceholderImages.length} placeholder image options for blueprint ${blueprintId}`);
      } catch (e) {
        console.warn("Could not fetch base mockup placeholders:", e);
      }
      const selectedPrimaryUrl = typeof placeholderPrimaryUrl === "string" ? placeholderPrimaryUrl : undefined;
      const selectedGalleryUrls = Array.isArray(placeholderGalleryUrls) ? placeholderGalleryUrls.map(String) : undefined;
      const selectedCustomUrls = Array.isArray(customPlaceholderUrls) ? customPlaceholderUrls.map(String) : undefined;
      let baseMockupImages = buildBaseMockupImagesFromOptions(
        availablePlaceholderImages,
        selectedPrimaryUrl,
        selectedGalleryUrls,
        selectedCustomUrls,
      );
      baseMockupImages = mergeCatalogSizeBlanksIfNeeded(
        parseInt(String(blueprintId), 10),
        baseMockupImages,
      );

      // Detect product type FIRST to determine sizeType
      // This is more reliable than checking dimensions since some dimensional products
      // may not have dimensions in the variant data
      const dimensionalKeywords = [
        "pillow", "cushion", "blanket", "throw", "mug", "cup", "tumbler",
        "poster", "print", "canvas", "frame", "artwork", "wall art",
        "phone case", "iphone", "samsung", "bag", "tote", "backpack", 
        "towel", "mat", "rug", "coaster", "mousepad", "sticker", "magnet",
        "puzzle", "ornament", "clock"
      ];
      const isDimensionalProduct = dimensionalKeywords.some(kw => matchesWord(combined, kw));
      
      // Check if we have dimensional sizes as backup
      const hasDimensionalSizes = sizes.some(s => s.width > 0 && s.height > 0);
      
      // Determine sizeType:
      // 1. Apparel always uses labels
      // 2. Known dimensional products use dimensional (even without parsed dimensions)
      // 3. Products with parsed dimensions use dimensional
      // 4. Unknown products without dimensions default to label
      let sizeType: string;
      if (isApparelProduct) {
        sizeType = "label";
      } else if (isDimensionalProduct || hasDimensionalSizes) {
        sizeType = "dimensional";
      } else {
        sizeType = "label";
      }

      const primaryPosition = pickPrimaryPrintPlaceholderDims(placeholderDimensions);
      const printAreaWidthPx = primaryPosition?.width || 0;
      const printAreaHeightPx = primaryPosition?.height || 0;
      
      // Detect phone cases for special aspect ratio handling
      const isPhoneCase = combined.includes("phone") || combined.includes("iphone") || 
                          combined.includes("samsung") || combined.includes("case");
      
      // Start with product-type-appropriate defaults
      let aspectRatio: string;
      if (isApparelProduct) {
        aspectRatio = "2:3";
      } else if (isPhoneCase) {
        aspectRatio = "9:16";
      } else {
        aspectRatio = "3:4";
      }
      
      // PRIORITY 1: Use front/chest print placeholder pixels (never sleeve/neck slots).
      if (printAreaWidthPx > 0 && printAreaHeightPx > 0) {
        if (isApparelProduct) {
          aspectRatio = resolveStandardApparelAspectRatioFromPlaceholders(placeholderDimensions, aspectRatio);
        } else {
          aspectRatio = computeAspectRatioFromPixelDims(printAreaWidthPx, printAreaHeightPx);
        }
      }
      // PRIORITY 2: Override with calculated dimensions from size names if no placeholder data
      else if (hasDimensionalSizes && sizes.length > 0) {
        const firstDimensionalSize = sizes.find(s => s.width > 0 && s.height > 0);
        if (firstDimensionalSize) {
          const w = firstDimensionalSize.width;
          const h = firstDimensionalSize.height;
          const divisor = gcd(w, h);
          const simplifiedW = w / divisor;
          const simplifiedH = h / divisor;
          aspectRatio = `${simplifiedW}:${simplifiedH}`;
        }
      }

      // Product type detection for designer type, shape, and bleed margin
      // IMPORTANT: Check apparel FIRST because descriptions often contain "print" (e.g. "print surface")
      // which would incorrectly match framed-print if checked first
      
      let designerType: string = "generic";
      let printShape: string = "rectangle";
      let bleedMarginPercent = 5;
      
      const positionKeys = Object.keys(placeholderDimensions);
      const isAllOverPrint =
        catalogEntry.kind === "aop" ||
        detectPrintifyAllOverPrint({
          name,
          description,
          blueprintId: Number.parseInt(String(blueprintId), 10),
        });

      // Detect apparel FIRST (before framed-print check)
      if (isApparelProduct) {
        // For AOP apparel, set designerType to 'all-over-print' to trigger multi-panel rendering
        if (isAllOverPrint) {
          designerType = "all-over-print";
        } else {
          designerType = "apparel";
        }
        printShape = "rectangle";
        bleedMarginPercent = 5;
      }
      // Detect pillows
      else if (combined.includes("pillow") || combined.includes("cushion")) {
        designerType = "pillow";
        if (combined.includes("round") || combined.includes("circle") || combined.includes("circular")) {
          printShape = "circle";
          bleedMarginPercent = 8;
        } else if (maxWidth === maxHeight && maxWidth > 0) {
          printShape = "square";
          bleedMarginPercent = 5;
        } else {
          printShape = "rectangle";
          bleedMarginPercent = 5;
        }
      }
      // Detect blankets
      else if (combined.includes("blanket") || combined.includes("throw")) {
        designerType = "pillow";
        printShape = "rectangle";
        bleedMarginPercent = 5;
      }
      // Detect mugs
      else if (combined.includes("mug") || combined.includes("cup") || combined.includes("tumbler")) {
        designerType = "mug";
        printShape = "rectangle";
        bleedMarginPercent = 3;
      }
      // Phone cases BEFORE framed-print — Printify copy often contains "print" and would
      // mis-tag slim cases as framed-print (breaks square browse window on storefront).
      else if (
        isPhoneCase ||
        Number.parseInt(String(blueprintId), 10) === slimPhoneCaseBlueprintId() ||
        combined.includes("phone case") ||
        (combined.includes("case") &&
          (combined.includes("iphone") ||
            combined.includes("samsung") ||
            combined.includes("galaxy") ||
            combined.includes("pixel")))
      ) {
        designerType = "generic";
        printShape = "rectangle";
        bleedMarginPercent = 3;
      }
      // Detect framed prints AFTER apparel (to avoid false positives from "print surface" in descriptions)
      else if (combined.includes("frame") || combined.includes("poster") || combined.includes("canvas") || 
               matchesWord(combined, "print") || combined.includes("wall art")) {
        designerType = "framed-print";
        printShape = "rectangle";
        bleedMarginPercent = 3;
      }
      // Detect round products
      else if (combined.includes("round") || combined.includes("circle") || combined.includes("coaster")) {
        printShape = "circle";
        bleedMarginPercent = 8;
      }

      // Detect double-sided print from description (decode HTML entities first)
      const decodedCombined = combined
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&amp;/g, '&').replace(/&quot;/g, '"')
        .replace(/<[^>]*>/g, ' ') // Strip HTML tags
        .toLowerCase();
      const hasBackPlaceholder = !!placeholderDimensions["back"];
      // Apparel (t-shirts, hoodies, etc.) always defaults to front-only print.
      // Having a "back" placeholder does NOT mean we should print on the back by default.
      // Only non-apparel products (pillows, tote bags, etc.) should be auto-flagged as double-sided.
      const doubleSidedPrintBase = designerType !== "apparel" && (
        hasBackPlaceholder ||
        decodedCombined.includes("double sided") ||
        decodedCombined.includes("double-sided") ||
        decodedCombined.includes("two sided") ||
        decodedCombined.includes("two-sided") ||
        decodedCombined.includes("both sides")
      );

      const catalogStorefrontMode = (catalogEntry as any).storefrontMockupMode ?? null;
      const catalogFulfillmentLayout =
        (catalogEntry as any).fulfillmentLayout ??
        (blueprintIdNum === 1300 ? "tote_folded_v1" : null);
      const toteFoldedImport = catalogFulfillmentLayout === "tote_folded_v1";
      const doubleSidedPrint = toteFoldedImport ? true : doubleSidedPrintBase;
      // Build the persisted placeholder positions list (all positions with their dimensions)
      const placeholderPositions = positionKeys.map(pos => ({
        position: pos,
        width: placeholderDimensions[pos].width,
        height: placeholderDimensions[pos].height,
      }));

      let importSizeIds: string[] = Array.isArray(selectedSizeIds) && selectedSizeIds.length > 0
        ? selectedSizeIds
        : sizes.map((s: { id: string }) => s.id);
      let importColorIds: string[] = Array.isArray(selectedColorIds) && selectedColorIds.length > 0
        ? selectedColorIds
        : frameColors.map((c: { id: string }) => c.id);
      let importVariantCount = countActiveVariantMapKeys(variantMap, importSizeIds, importColorIds);
      const explicitVariantPick =
        (Array.isArray(selectedSizeIds) && selectedSizeIds.length > 0) ||
        (Array.isArray(selectedColorIds) && selectedColorIds.length > 0);
      // Setup → Activate has no size/color picker. Auto-trim to Shopify's 100
      // variant cap (prefer all sizes, fewer colors). Products Import still
      // errors when the merchant explicitly picks too many.
      if (importVariantCount > SHOPIFY_MAX_VARIANTS_PER_PRODUCT) {
        if (opts?.autoCapVariants || !explicitVariantPick) {
          const capped = capVariantSelectionForShopifyLimit(
            importSizeIds,
            importColorIds,
            variantMap,
          );
          importSizeIds = capped.sizeIds;
          importColorIds = capped.colorIds;
          importVariantCount = capped.variantCount;
          console.log(
            `[Import] Auto-capped blueprint ${blueprintIdNum} to ${importVariantCount} variants ` +
              `(${importSizeIds.length} sizes × ${importColorIds.length} colors)`,
          );
          if (importVariantCount > SHOPIFY_MAX_VARIANTS_PER_PRODUCT) {
            return res.status(400).json({
              error: `Too many variants (${importVariantCount}) even after auto-select. Shopify allows a maximum of ${SHOPIFY_MAX_VARIANTS_PER_PRODUCT} per product.`,
              code: "SHOPIFY_VARIANT_LIMIT",
              variantCount: importVariantCount,
            });
          }
        } else {
          return res.status(400).json({
            error: `Too many variants (${importVariantCount}). Shopify allows a maximum of ${SHOPIFY_MAX_VARIANTS_PER_PRODUCT} per product. Select fewer sizes or colors.`,
            code: "SHOPIFY_VARIANT_LIMIT",
            variantCount: importVariantCount,
          });
        }
      }

      const importPrintifyVariantIds = [
        ...new Set(
          Object.values(variantMap)
            .map((e: any) => Number(e?.printifyVariantId))
            .filter((id) => Number.isFinite(id) && id > 0),
        ),
      ];
      const { costs: resolvedImportCosts, source: importCostsSource } =
        await resolvePrintifyProductionCosts({
          merchant,
          blueprintId: blueprintIdNum,
          providerId,
          catalogVariants: variants,
          printifyVariantIds: importPrintifyVariantIds,
          baseMockupImages,
        });
      const printifyCostsAtImport =
        Object.keys(resolvedImportCosts).length > 0
          ? serializePrintifyCostsCache(resolvedImportCosts)
          : null;
      if (printifyCostsAtImport) {
        console.log(
          `[Import] Stored ${Object.keys(resolvedImportCosts).length} production costs via ${importCostsSource}`,
        );
      } else {
        console.warn(
          `[Import] No production costs resolved for blueprint ${blueprintIdNum} — customizer markup pricing will require manual entry until costs are refreshed`,
        );
      }

      // Create the product type with parsed data
      const initialFlatStatus =
        catalogEntry.kind === "printify"
          ? "unsupported"
          : catalogEntry.kind === "flat" && canonicalManifest
            ? "ready"
            : catalogEntry.kind === "flat"
              ? "pending"
              : catalogEntry.kind === "aop"
                ? "unsupported"
                : "pending";

      const productType = await storage.createProductType({
        merchantId: merchant.id,
        name,
        description: resolvedDescription || null,
        printifyBlueprintId: blueprintIdNum,
        printifyProviderId: providerId,
        sizes: JSON.stringify(sizes),
        frameColors: JSON.stringify(frameColors),
        variantMap: JSON.stringify(variantMap),
        // Empty [] from a failed/partial variants wizard must mean "select all", not
        // "intentionally none" (that would hide storefront color/size dropdowns).
        // Use importSizeIds / importColorIds (may be auto-capped for Setup Activate).
        selectedSizeIds: JSON.stringify(importSizeIds),
        selectedColorIds: JSON.stringify(importColorIds),
        aspectRatio,
        printShape,
        // Store only physical dimensions (inches) for unit consistency
        // Pixel dimensions are used only for aspect ratio calculation above
        printAreaWidth: maxWidth || null,
        printAreaHeight: maxHeight || null,
        bleedMarginPercent,
        designerType,
        sizeType,
        hasPrintifyMockups: true,
        baseMockupImages: JSON.stringify(baseMockupImages),
        primaryMockupIndex: 0,
        doubleSidedPrint,
        isAllOverPrint,
        placeholderPositions: JSON.stringify(placeholderPositions),
        panelFlatLayImages: JSON.stringify(panelFlatLayImages),
        colorOptionName: blueprintColorOptionName,
        flatCalibrationStatus: initialFlatStatus,
        panelMappingTemplate:
          catalogEntry.kind === "aop" ? catalogEntry.panelMappingTemplate ?? null : null,
        storefrontMockupMode: catalogStorefrontMode,
        fulfillmentLayout: catalogFulfillmentLayout,
        fabricWeaveTexture: resolveFabricWeaveTexture({
          fabricWeaveTexture: catalogEntry.fabricWeaveTexture,
          printifyBlueprintId: blueprintIdNum,
        }),
        isActive: true,
        sortOrder: existingTypes.length,
        ...(printifyCostsAtImport ? { printifyCosts: printifyCostsAtImport } : {}),
      });

      if (toteFoldedImport) {
        await storage.updateProductType(productType.id, {
          doubleSidedPrint: true,
          flatCalibrationStatus: "unsupported",
          storefrontMockupMode: catalogStorefrontMode || "flat",
          fulfillmentLayout: "tote_folded_v1",
        });
      }

      // Seed shared canonical calibration (instant — no per-merchant harvest).
      if (catalogEntry.kind === "flat" && canonicalManifest) {
        await storage.updateProductType(productType.id, {
          onTheFlyTier: canonicalFlatMeta?.tier ?? canonicalManifest.tier,
          flatCalibrationStatus: "ready",
          flatCalibration: JSON.stringify(
            merchantManifestFromCanonical(canonicalManifest, productType.id, productType.name),
          ),
        });
      } else if (catalogEntry.kind === "aop" && catalogEntry.panelMappingTemplate && catalogEntry.status === "published") {
        await storage.updateProductType(productType.id, {
          panelMappingTemplate: catalogEntry.panelMappingTemplate,
          flatCalibrationStatus: "unsupported",
        });
      } else if (catalogEntry.kind === "printify") {
        await storage.updateProductType(productType.id, {
          flatCalibrationStatus: "unsupported",
        });
      }

      res.json(productType);

      // No per-merchant harvest for catalog-managed products with shared calibration.
      const skipHarvest =
        catalogEntry.kind === "printify" ||
        catalogEntry.kind === "aop" ||
        (catalogEntry.kind === "flat" && !!canonicalManifest) ||
        (isOperator && catalogEntry.kind === "aop");
      if (!skipHarvest) {
        kickoffFlatCalibration({
          productTypeId: productType.id,
          name: productType.name,
          blueprintId: blueprintIdNum,
          providerId,
          token: merchant.printifyApiToken,
          shopId: merchant.printifyShopId,
          isAllOverPrint,
          designerType: productType.designerType,
          frameColors,
          sizes,
          variantMap,
        });
      }
    } catch (error) {
      console.error("Error importing Printify blueprint:", error);
      res.status(500).json({ error: "Failed to import blueprint" });
    }
  }

  app.post("/api/admin/printify/import", isAuthenticated, async (req: any, res: Response) => {
    await handlePrintifyImportRequest(req, res);
  });

  // POST /api/admin/product-types/:id/calibrate-flat - (Re)run on-the-fly flat
  // mockup calibration for an existing product. Returns 202 and runs in the
  // background; poll the product's flatCalibrationStatus for progress.
  app.post("/api/admin/product-types/:id/calibrate-flat", isAuthenticated, async (req: any, res: Response) => {
    try {
      if (!isPlatformAdminRequest(req)) {
        return res.status(403).json({
          error: "Calibration is managed by the platform via the Platform Catalog.",
          code: "OPERATOR_ONLY",
        });
      }
      const userId = req.user.claims.sub;
      const productTypeId = parseInt(req.params.id);
      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) return res.status(404).json({ error: "Merchant not found" });
      const productType = await storage.getProductType(productTypeId);
      const accessErr = adminProductTypeAccessError(req, productType, merchant);
      if (accessErr) {
        return res.status(accessErr.status).json({ error: accessErr.error, code: accessErr.code });
      }

      const forceFromCanonical = req.body?.forceFromCanonical === true;
      const synced = await syncProductTypeFromCanonicalCalibration(productType!, {
        allowUnpublishedHarvest: true,
        forceOverwrite: forceFromCanonical,
      });
      if (synced.synced) {
        return res.status(200).json({
          status: "ready",
          productTypeId: productType.id,
          syncedFromCanonical: true,
          forceFromCanonical,
        });
      }

      if (forceFromCanonical) {
        return res.status(404).json({
          error:
            "No usable platform canonical calibration for this blueprint. Harvest (and preferably Publish) it in Platform Catalog first.",
          code: "CANONICAL_MISSING",
        });
      }

      kickoffFlatCalibration({
        productTypeId: productType.id,
        name: productType.name,
        blueprintId: productType.printifyBlueprintId,
        providerId: productType.printifyProviderId,
        token: merchant.printifyApiToken,
        shopId: merchant.printifyShopId,
        isAllOverPrint: productType.isAllOverPrint,
        designerType: productType.designerType,
        frameColors: productType.frameColors,
        sizes: productType.sizes,
        variantMap: productType.variantMap,
        forceFlatHarvest: (productType as any).forceFlatHarvest,
        fulfillmentLayout: (productType as any).fulfillmentLayout,
      });
      res.status(202).json({ status: "running", productTypeId: productType.id });
    } catch (error) {
      console.error("Error starting flat calibration:", error);
      res.status(500).json({ error: "Failed to start calibration" });
    }
  });

  // POST /api/admin/product-types/:id/test-printify-order - Bake the print file
  // for a chosen (or latest) design and create a DRAFT Printify order so the
  // merchant can verify, in Printify, that the print file matches the on-screen
  // design BEFORE going live. Never sends to production / never charges.
  // Mandatory per-product pre-launch check for flat/mesh on-the-fly products.
  app.post("/api/admin/product-types/:id/test-printify-order", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const productTypeId = parseInt(req.params.id);
      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) return res.status(404).json({ error: "Merchant not found" });
      const productType = await storage.getProductType(productTypeId);
      const accessErr = adminProductTypeAccessError(req, productType, merchant);
      if (accessErr) {
        return res.status(accessErr.status).json({ error: accessErr.error, code: accessErr.code });
      }
      if (!merchant.printifyApiToken || !merchant.printifyShopId) {
        return res.status(400).json({ error: "Printify credentials not configured for this merchant" });
      }
      if (productType.onTheFlyTier !== "flat" && productType.onTheFlyTier !== "mesh") {
        const toteFolded = usesToteFoldedFulfillment({
          isAllOverPrint: productType.isAllOverPrint,
          storefrontMockupMode: (productType as any).storefrontMockupMode,
          fulfillmentLayout: (productType as any).fulfillmentLayout,
          printifyBlueprintId: productType.printifyBlueprintId,
        });
        // AOP products are also eligible — their per-panel print files (captured on
        // apply) are submitted directly as the order's print_areas.
        if (!toteFolded && !productType.isAllOverPrint) {
          return res.status(400).json({
            error: `This product is not a flat/mesh on-the-fly product (tier=${productType.onTheFlyTier ?? "none"}). Calibrate it first.`,
          });
        }
      }

      const designId = typeof req.body?.designId === "string" ? req.body.designId : null;
      let result;
      try {
        result = await submitFlatTestOrder({ productType, designId });
      } catch (e: any) {
        return res.status(400).json({ error: e?.message || "Failed to create test order" });
      }

      if (result.status === "failed") {
        return res.status(502).json({ error: result.error || "Printify rejected order", ...result });
      }
      if (result.status === "skipped") {
        return res.status(400).json({ error: result.skippedReasons.join("; ") || "No eligible lines", ...result });
      }

      const toteFolded = usesToteFoldedFulfillment({
        isAllOverPrint: productType.isAllOverPrint,
        storefrontMockupMode: (productType as any).storefrontMockupMode,
        fulfillmentLayout: (productType as any).fulfillmentLayout,
        printifyBlueprintId: productType.printifyBlueprintId,
      });

      return res.json({
        success: true,
        draft: true,
        message: toteFolded
          ? "Created DRAFT Printify order with tote_folded_v1 print file (2650×5250). Open Printify to confirm the folded layout."
          : "Created DRAFT Printify order. Open Printify to verify the print file matches the on-screen design.",
        designId: result.designId,
        printifyOrderId: result.printifyOrderId,
        printFileUrls: result.printFileUrls,
        printifyOrderUrl: result.printifyOrderId
          ? `https://printify.com/app/orders/${merchant.printifyShopId}/${result.printifyOrderId}`
          : undefined,
      });
    } catch (error) {
      console.error("Error creating test Printify order:", error);
      res.status(500).json({ error: "Failed to create test order" });
    }
  });

  // DELETE /api/admin/product-types/:id - Delete a product type
  // GET /api/admin/product-types/:id/svg-debug
  // Diagnostic: shows stored panelFlatLayImages, tests CDN accessibility, and fetches
  // the correct flat-lay SVG URLs from the Printify API so the merchant can see what's wrong.
  app.get("/api/admin/product-types/:id/svg-debug", isAuthenticated, asyncHandler(async (req: any, res: Response) => {
    const userId = req.user.claims.sub;
    const productTypeId = parseInt(req.params.id);
    const merchant = await storage.getMerchantByUserId(userId);
    if (!merchant) return res.status(404).json({ error: "Merchant not found" });

    const pt = await storage.getProductType(productTypeId);
    if (!pt || pt.merchantId !== merchant.id) return res.status(404).json({ error: "Product type not found" });

    // Parse what is stored in the DB
    let storedImages: Record<string, string> = {};
    try {
      storedImages = typeof pt.panelFlatLayImages === "string"
        ? JSON.parse(pt.panelFlatLayImages || "{}")
        : (pt.panelFlatLayImages as any) || {};
    } catch { storedImages = {}; }

    // Test each stored URL from the server side (no auth)
    const urlTests: Record<string, { status: number | string; contentType: string | null }> = {};
    await Promise.all(Object.entries(storedImages).map(async ([pos, url]) => {
      try {
        const r = await fetch(url, { headers: { Accept: "image/*,*/*" }, signal: AbortSignal.timeout(8000) });
        urlTests[pos] = { status: r.status, contentType: r.headers.get("content-type") };
      } catch (e: any) {
        urlTests[pos] = { status: e?.message || "fetch error", contentType: null };
      }
    }));

    // Fetch the live views from Printify API for this blueprint/provider combo
    let printifyViews: any[] = [];
    let printifyViewsError: string | null = null;
    if (pt.printifyBlueprintId && pt.printifyProviderId && merchant.printifyApiToken) {
      try {
        const vr = await fetch(
          `https://api.printify.com/v1/catalog/blueprints/${pt.printifyBlueprintId}/print_providers/${pt.printifyProviderId}/variants.json`,
          { headers: { Authorization: `Bearer ${merchant.printifyApiToken}` }, signal: AbortSignal.timeout(15000) }
        );
        if (vr.ok) {
          const vdata = await vr.json();
          printifyViews = vdata.views || [];
        } else {
          printifyViewsError = `Printify API ${vr.status}`;
        }
      } catch (e: any) {
        printifyViewsError = e?.message || "fetch error";
      }
    } else {
      printifyViewsError = "Missing blueprintId, providerId, or Printify API token";
    }

    // Test Printify-returned view URLs
    const printifyUrlTests: Record<string, { src: string; status: number | string; contentType: string | null }> = {};
    await Promise.all(printifyViews.map(async (view: any) => {
      const src = view.files?.[0]?.src;
      if (!src || !view.position) return;
      try {
        const r = await fetch(src, { headers: { Accept: "image/*,*/*" }, signal: AbortSignal.timeout(8000) });
        printifyUrlTests[view.position] = { src, status: r.status, contentType: r.headers.get("content-type") };
      } catch (e: any) {
        printifyUrlTests[view.position] = { src, status: e?.message || "fetch error", contentType: null };
      }
    }));

    res.json({
      productType: {
        id: pt.id,
        name: pt.name,
        printifyBlueprintId: pt.printifyBlueprintId,
        printifyProviderId: pt.printifyProviderId,
        storedPanelFlatLayImages: storedImages,
        storedImageCount: Object.keys(storedImages).length,
      },
      cdnUrlTests: urlTests,
      printifyApiViews: { views: printifyViews.map((v: any) => ({ position: v.position, src: v.files?.[0]?.src })), error: printifyViewsError },
      printifyApiUrlTests: printifyUrlTests,
    });
  }));

  // POST /api/admin/product-types/:id/refresh-panel-svgs
  // Re-fetches flat-lay SVG URLs from Printify API and saves them to panelFlatLayImages.
  app.post("/api/admin/product-types/:id/refresh-panel-svgs", isAuthenticated, asyncHandler(async (req: any, res: Response) => {
    const userId = req.user.claims.sub;
    const productTypeId = parseInt(req.params.id);
    const merchant = await storage.getMerchantByUserId(userId);
    if (!merchant) return res.status(404).json({ error: "Merchant not found" });

    const pt = await storage.getProductType(productTypeId);
    if (!pt || pt.merchantId !== merchant.id) return res.status(404).json({ error: "Product type not found" });

    if (!pt.printifyBlueprintId || !pt.printifyProviderId || !merchant.printifyApiToken) {
      return res.status(400).json({ error: "Missing blueprintId, providerId, or Printify API token" });
    }

    const vr = await fetch(
      `https://api.printify.com/v1/catalog/blueprints/${pt.printifyBlueprintId}/print_providers/${pt.printifyProviderId}/variants.json`,
      { headers: { Authorization: `Bearer ${merchant.printifyApiToken}` } }
    );
    if (!vr.ok) return res.status(502).json({ error: `Printify API ${vr.status}` });

    const vdata = await vr.json();
    const views: any[] = vdata.views || [];
    const newImages: Record<string, string> = {};
    for (const view of views) {
      if (view.position && view.files?.[0]?.src) newImages[view.position] = view.files[0].src;
    }

    if (Object.keys(newImages).length === 0) {
      return res.status(200).json({ message: "Printify returned no views for this product. panelFlatLayImages unchanged.", views: [] });
    }

    // Alias leg/side naming
    if (newImages.left_leg && !newImages.left_side) newImages.left_side = newImages.left_leg;
    if (newImages.right_leg && !newImages.right_side) newImages.right_side = newImages.right_leg;
    if (newImages.left_side && !newImages.left_leg) newImages.left_leg = newImages.left_side;
    if (newImages.right_side && !newImages.right_leg) newImages.right_leg = newImages.right_side;

    await storage.updateProductType(productTypeId, { panelFlatLayImages: JSON.stringify(newImages) });
    console.log(`[refresh-panel-svgs] Updated productType ${productTypeId} with ${Object.keys(newImages).length} views:`, Object.keys(newImages).join(", "));

    res.json({ success: true, panelFlatLayImages: newImages, count: Object.keys(newImages).length });
  }));

  // POST /api/admin/aop-masks/upload
  // Store self-hosted AOP panel masks (SVG strings) for a blueprint.
  // Body: JSON { blueprintId: "256", masks: { left_leg: "<svg...>", right_leg: "..." } }
  // Written to dist/public/aop-masks/{blueprintId}/{position}.svg so they are immediately
  // served by the aop-mask endpoint without a re-deploy.
  // For bulk ingestion from template ZIPs, use the CLI script: scripts/import-aop-masks.js
  app.post("/api/admin/aop-masks/upload", isAuthenticated, asyncHandler(async (req: any, res: Response) => {
    const { blueprintId, masks } = req.body as { blueprintId: string; masks: Record<string, string> };
    if (!blueprintId || !/^\d+$/.test(String(blueprintId))) {
      return res.status(400).json({ error: "Missing or invalid blueprintId" });
    }
    if (!masks || typeof masks !== "object" || Object.keys(masks).length === 0) {
      return res.status(400).json({ error: "masks must be a non-empty object of {position: svgString}" });
    }

    declare const __dirname: string | undefined;
    const _d = typeof __dirname !== "undefined" ? __dirname : process.cwd();
    const candidates = [
      path.join(_d, "public", "aop-masks", String(blueprintId)),
      path.join(_d, "../public", "aop-masks", String(blueprintId)),
      path.join(process.cwd(), "client", "public", "aop-masks", String(blueprintId)),
    ];
    const outDir = candidates.find(c => {
      try { fs.mkdirSync(c, { recursive: true }); return true; } catch { return false; }
    });
    if (!outDir) return res.status(500).json({ error: "Could not create output directory" });

    const written: string[] = [];
    for (const [position, svgContent] of Object.entries(masks)) {
      if (!/^[a-z0-9_]+$/.test(position)) {
        console.warn(`[aop-masks/upload] Skipping invalid position name: ${position}`);
        continue;
      }
      if (typeof svgContent !== "string" || !svgContent.trim().startsWith("<")) {
        console.warn(`[aop-masks/upload] Skipping position ${position}: not valid SVG`);
        continue;
      }
      const dest = path.join(outDir, `${position}.svg`);
      fs.writeFileSync(dest, svgContent.trim(), "utf8");
      written.push(position);
      console.log(`[aop-masks/upload] Wrote ${dest}`);
    }

    res.json({ success: true, blueprintId, outDir, written });
  }));

  // POST /api/admin/product-types/:id/refresh-images - Refresh product images from Printify
  app.post("/api/admin/product-types/:id/refresh-images", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const productTypeId = parseInt(req.params.id);

      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) {
        return res.status(404).json({ error: "Merchant not found" });
      }

      const printifyToken = resolveCatalogPrintifyToken(merchant);
      if (!printifyToken) {
        return res.status(400).json({ error: "Printify API token not configured" });
      }

      const productType = await storage.getProductType(productTypeId);
      const accessErr = adminProductTypeAccessError(req, productType, merchant);
      if (accessErr) {
        return res.status(accessErr.status).json({ error: accessErr.error, code: accessErr.code });
      }

      if (!productType.printifyBlueprintId) {
        return res.status(400).json({ error: "Product type is not linked to Printify" });
      }

      let providerId = productType.printifyProviderId as number | null | undefined;
      if (!providerId) {
        const provRes = await fetchWithRetry(
          `https://api.printify.com/v1/catalog/blueprints/${productType.printifyBlueprintId}/print_providers.json`,
          { headers: { Authorization: `Bearer ${printifyToken}`, "Content-Type": "application/json" } },
          2,
          800,
        );
        if (provRes.ok) {
          const provs = await provRes.json();
          providerId = Array.isArray(provs) && provs.length
            ? (provs[0].id ?? provs[0].print_provider_id)
            : undefined;
        }
      }
      if (!providerId) {
        return res.status(400).json({ error: "Product type is not linked to a Printify provider" });
      }

      const existingImages = typeof productType.baseMockupImages === "string"
        ? JSON.parse(productType.baseMockupImages || "{}")
        : productType.baseMockupImages || {};
      const availablePlaceholderImages = await fetchPrintifyPlaceholderOptions(
        printifyToken,
        productType.printifyBlueprintId,
        providerId,
      );
      let baseMockupImages = buildBaseMockupImagesFromOptions(
        availablePlaceholderImages,
        existingImages.primary,
        existingImages.gallery,
        existingImages.custom,
      );
      // Keep existing size blanks if refresh ran before shared assets were uploaded.
      if (
        existingImages.blanksBySize &&
        typeof existingImages.blanksBySize === "object" &&
        !baseMockupImages.blanksBySize
      ) {
        baseMockupImages.blanksBySize = existingImages.blanksBySize;
      }
      baseMockupImages = mergeCatalogSizeBlanksIfNeeded(
        productType.printifyBlueprintId,
        baseMockupImages,
      );

      // Check if we found any images
      if (!baseMockupImages.front && !baseMockupImages.lifestyle) {
        return res.status(400).json({ 
          error: "No product images available from Printify for this blueprint",
          hint: "This product type may not have catalog images. You can add a custom mockup template URL instead."
        });
      }

      // Update the product type with new images
      const updated = await storage.updateProductType(productTypeId, {
        baseMockupImages: JSON.stringify(baseMockupImages),
        ...(!(productType as any).printifyProviderId && providerId
          ? { printifyProviderId: providerId }
          : {}),
      });

      res.json({ 
        success: true, 
        baseMockupImages,
        productType: updated 
      });
    } catch (error) {
      console.error("Error refreshing product images:", error);
      res.status(500).json({ error: "Failed to refresh images" });
    }
  });

  // POST /api/admin/product-types/:id/refresh-variants - Re-fetch sizes and colors from Printify
  // This re-runs the variant parsing logic to fix products with missing sizes/colors
  app.post("/api/admin/product-types/:id/refresh-variants", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const productTypeId = parseInt(req.params.id);

      const merchant = await storage.getMerchantByUserId(userId);
      if (!merchant) {
        return res.status(404).json({ error: "Merchant not found" });
      }

      if (!merchant.printifyApiToken) {
        return res.status(400).json({ error: "Printify API token not configured" });
      }

      const productType = await storage.getProductType(productTypeId);
      const accessErr = adminProductTypeAccessError(req, productType, merchant);
      if (accessErr) {
        return res.status(accessErr.status).json({ error: accessErr.error, code: accessErr.code });
      }

      if (!productType.printifyBlueprintId || !productType.printifyProviderId) {
        return res.status(400).json({ error: "Product type not linked to Printify blueprint" });
      }

      const blueprintId = productType.printifyBlueprintId;
      const providerId = productType.printifyProviderId;

      // Full catalog so fully OOS colors re-enter variantMap / OOS denominator.
      const dualRefresh = await fetchPrintifyProviderVariantsDual(
        blueprintId,
        providerId,
        merchant.printifyApiToken,
        {
          fetchFn: (url, init) => fetchWithRetry(String(url), init || {}, 3, 1500),
        },
      );
      const variants = dualRefresh.variants;

      // Log first few variants to debug
      console.log(
        `[Refresh Variants] Blueprint ${blueprintId} returned ${variants.length} variants (fullCatalog=${dualRefresh.usedFullCatalog})`,
      );
      if (variants.length > 0) {
        console.log(`[Refresh Variants] Sample variant:`, JSON.stringify(variants[0]).slice(0, 500));
        console.log(`[Refresh Variants] First 5 variant titles:`, variants.slice(0, 5).map((v: any) => v.title));
      }

      // Parse variants to extract sizes and colors (same logic as import)
      const sizesMap = new Map<string, { id: string; name: string; width: number; height: number }>();
      const colorsMap = new Map<string, { id: string; name: string; hex: string }>();
      const variantMap: Record<string, { printifyVariantId: number; providerId: number }> = {};

      // Known size patterns
      const apparelSizes = ["XXS", "XS", "S", "M", "L", "XL", "2XL", "3XL", "4XL", "5XL", "XXL", "XXXL"];
      const apparelSizesLower = apparelSizes.map(s => s.toLowerCase());
      const namedSizes = ["small", "medium", "large", "extra large", "king", "queen", "twin", "full", "one size"];

      const looksLikeSize = (str: string): boolean => {
        const lower = str.toLowerCase().trim();
        if (lower.match(/^\d+[""']?\s*[xX×]\s*\d+[""']?$/)) return true;
        if (apparelSizesLower.includes(lower)) return true;
        if (namedSizes.includes(lower)) return true;
        if (lower.match(/^\d+\s*oz$/i)) return true;
        // Phone/device models
        if (lower.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i)) return true;
        if (lower.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i)) return true;
        if (lower.match(/^pixel\s+(\d|fold|pro)/i)) return true;
        if (lower.match(/^samsung\s+(galaxy|note)/i)) return true;
        if (lower.match(/^oneplus\s+\d/i)) return true;
        if (lower.match(/^for\s+(iphone|galaxy|pixel|samsung)/i)) return true;
        return false;
      };

      // Color hex lookup map
      const colorHexMap: Record<string, string> = {
        "black": "#1a1a1a", "white": "#f5f5f5", "red": "#C41E3A", "blue": "#2563EB",
        "navy": "#1B2838", "green": "#22C55E", "yellow": "#FACC15", "orange": "#F97316",
        "pink": "#EC4899", "purple": "#A855F7", "gray": "#9E9E9E", "grey": "#9E9E9E",
        "brown": "#795548", "beige": "#F5F5DC", "cream": "#FFFDD0", "tan": "#D2B48C",
        "gold": "#FFD700", "silver": "#C0C0C0", "forest": "#228B22", "maroon": "#800000",
        "coral": "#FF7F50", "teal": "#008080", "aqua": "#00FFFF", "mint": "#98FF98",
        "lavender": "#E6E6FA", "peach": "#FFCBA4", "olive": "#808000", "charcoal": "#36454F",
      };

      for (const variant of variants) {
        const title = variant.title || "";
        const options = variant.options || {};

        const normalizedTitle = title
          .replace(/[″″‶‴]/g, '"')
          .replace(/[′′‵]/g, "'")
          .replace(/[""]/g, '"')
          .replace(/['']/g, "'");

        let extractedSizeId = "";

        // Try dimensional sizes
        const dimMatch = normalizedTitle.match(/(\d+)[""']?\s*[xX×]\s*(\d+)[""']?/);
        if (dimMatch) {
          const width = parseInt(dimMatch[1]);
          const height = parseInt(dimMatch[2]);
          extractedSizeId = `${width}x${height}`;
          const sizeName = `${width}" x ${height}"`;
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeName, width, height });
          }
        }

        // Check options for size
        if (!extractedSizeId && (options.size || options.Size)) {
          const sizeVal = options.size || options.Size;
          extractedSizeId = normalizeApparelSizeId(sizeVal);
          if (!sizesMap.has(extractedSizeId)) {
            sizesMap.set(extractedSizeId, { id: extractedSizeId, name: sizeVal, width: 0, height: 0 });
          }
        }

        // Extract from title patterns
        if (!extractedSizeId && title) {
          // Printify uses " / " (space-slash-space) as the separator between size and color/option.
          // Combined phone model names like "iPhone 12/12 Pro" use a bare "/" without spaces.
          // Splitting on " / " correctly preserves combined model names as a single token.
          const hasSeparator = title.includes(" / ");
          const parts = hasSeparator
            ? title.split(" / ").map((p: string) => p.trim())
            : title.split("/").map((p: string) => p.trim());
          for (const part of parts) {
            const volumeMatch = part.match(/^(\d+)\s*oz$/i);
            if (volumeMatch) {
              extractedSizeId = `${volumeMatch[1]}oz`;
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: `${volumeMatch[1]}oz`, width: 0, height: 0 });
              }
              break;
            }
            if (apparelSizesLower.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            // Named sizes (Small, Medium, Large, King, Queen, One Size, etc.)
            if (namedSizes.includes(part.toLowerCase())) {
              extractedSizeId = normalizeApparelSizeId(part);
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
            // Phone/device models (iPhone 14, Galaxy S23, Pixel 7, etc.)
            if (part.match(/^iphone\s+(\d|x|xs|xr|se|pro|plus|max)/i) ||
                part.match(/^galaxy\s+(s\d|a\d|note|z\s*(fold|flip)|ultra)/i) ||
                part.match(/^pixel\s+(\d|fold|pro)/i) ||
                part.match(/^samsung\s+(galaxy|note)/i) ||
                part.match(/^oneplus\s+\d/i) ||
                part.match(/^for\s+(iphone|galaxy|pixel|samsung)/i)) {
              extractedSizeId = part.toLowerCase().replace(/\s+/g, '_');
              if (!sizesMap.has(extractedSizeId)) {
                sizesMap.set(extractedSizeId, { id: extractedSizeId, name: part, width: 0, height: 0 });
              }
              break;
            }
          }
        }

        // Fallback: first non-color title part when size still unknown (parity with import)
        if (!extractedSizeId && title && title.includes("/")) {
          const parts = title.split("/").map((p: string) => p.trim());
          const firstPart = parts[0];
          if (firstPart && !firstPart.match(/^(black|white|red|blue|green|yellow|pink|purple|orange|gray|grey|navy|brown|beige|cream|tan)/i)) {
            extractedSizeId = normalizeApparelSizeId(firstPart);
            if (!sizesMap.has(extractedSizeId)) {
              sizesMap.set(extractedSizeId, { id: extractedSizeId, name: firstPart, width: 0, height: 0 });
            }
          }
        }

        const colorName = extractPrintifyColorName(
          options,
          title,
          (productType as any).colorOptionName,
        );

        // Log what we found for debugging
        if (variants.indexOf(variant) < 3) {
          console.log(
            `[Refresh Variants] Variant "${title}" -> size: "${extractedSizeId}", color: "${colorName}", options:`,
            Object.keys(options),
          );
        }

        let extractedColorId = "";
        if (colorName) {
          extractedColorId = slugPrintifyColorId(colorName);
          if (!colorsMap.has(colorName.toLowerCase())) {
            const { hex } = resolvePrintifyColorHex(colorName);
            colorsMap.set(colorName.toLowerCase(), { id: extractedColorId, name: colorName, hex });
          }
        }

        // Add to variantMap
        if (extractedSizeId || extractedColorId) {
          const mapKey = variantMapKey(extractedSizeId || "default", extractedColorId || "default");
          variantMap[mapKey] = { printifyVariantId: variant.id, providerId };
        }
      }

      let sizes = Array.from(sizesMap.values());
      const frameColors = Array.from(colorsMap.values());

      // Fallback: If no sizes extracted, create from product name or use default
      // This handles single-variant products and products where size wasn't parseable
      if (sizes.length === 0) {
        const sizeFromName = productType.name.match(/(\d+\s*oz)/i);
        const defaultSizeId = sizeFromName ? sizeFromName[1].toLowerCase().replace(/\s+/g, '') : "default";
        const defaultSizeName = sizeFromName ? sizeFromName[1] : "One Size";
        sizes = [{ id: defaultSizeId, name: defaultSizeName, width: 0, height: 0 }];
        console.log(`[Refresh Variants] Created fallback size "${defaultSizeName}" (id: ${defaultSizeId})`);

        // Update variantMap keys if we extracted a size from name
        if (defaultSizeId !== "default") {
          for (const key of Object.keys(variantMap)) {
            if (key.startsWith("default:")) {
              const colorId = key.slice(8);
              const newKey = `${defaultSizeId}:${colorId}`;
              variantMap[newKey] = variantMap[key];
              delete variantMap[key];
            }
          }
        }

        // For single-variant products with no variantMap entries, create one
        if (Object.keys(variantMap).length === 0 && variants.length > 0) {
          const variantKey = `${defaultSizeId}:default`;
          variantMap[variantKey] = { printifyVariantId: variants[0].id, providerId };
          console.log(`[Refresh Variants] Created fallback variantMap entry: ${variantKey}`);
        }
      }

      // Update product type.
      // Preserve intentional deselections. Newly appeared colors are only auto-selected
      // when they have at least one in-stock size — fully OOS newcomers (Deep Heather with
      // no providers, White/Black at JAMS) stay in frameColors/variantMap for Edit Variants
      // but are not forced onto the storefront until the merchant checks them.
      const existingSizeIds: string[] = typeof productType.selectedSizeIds === 'string'
        ? JSON.parse(productType.selectedSizeIds || '[]')
        : productType.selectedSizeIds || [];
      const existingColorIds: string[] = typeof productType.selectedColorIds === 'string'
        ? JSON.parse(productType.selectedColorIds || '[]')
        : productType.selectedColorIds || [];
      const previousSizes: Array<{ id?: string }> = typeof productType.sizes === 'string'
        ? JSON.parse(productType.sizes || '[]')
        : productType.sizes || [];
      const previousColors: Array<{ id?: string }> = typeof productType.frameColors === 'string'
        ? JSON.parse(productType.frameColors || '[]')
        : productType.frameColors || [];

      const colorsWithStock = new Set(
        colorIdsWithInStockVariants({
          variantMap,
          inStockVariantIds: dualRefresh.inStockVariantIds,
        }),
      );
      const refreshedColorIds = frameColors.map((c: { id: string }) => c.id);
      const previousColorIdSet = new Set(
        previousColors.map((c) => String(c.id || "")).filter(Boolean),
      );
      const autoSelectNewColors = refreshedColorIds.filter(
        (id: string) => !previousColorIdSet.has(id) && colorsWithStock.has(id),
      );

      const finalSizeIds = mergeNewlyAppearedSelectionIds({
        existingSelectedIds: existingSizeIds,
        previousOptionIds: previousSizes.map((s) => String(s.id || "")).filter(Boolean),
        refreshedOptionIds: sizes.map((s: { id: string }) => s.id),
      });
      const finalColorIds = mergeNewlyAppearedSelectionIds({
        existingSelectedIds: existingColorIds,
        previousOptionIds: previousColors.map((c) => String(c.id || "")).filter(Boolean),
        refreshedOptionIds: refreshedColorIds,
        autoSelectNewlyAppearedIds: autoSelectNewColors,
      });

      const refreshedCatalogCosts = extractCostsFromCatalogVariants(variants);
      let finalRefreshCosts = refreshedCatalogCosts;
      if (Object.keys(finalRefreshCosts).length === 0) {
        const refreshPrintifyVariantIds = [
          ...new Set(
            Object.values(variantMap)
              .map((e: any) => Number(e?.printifyVariantId))
              .filter((id) => Number.isFinite(id) && id > 0),
          ),
        ];
        const baseMockupImages = typeof productType.baseMockupImages === "string"
          ? JSON.parse(productType.baseMockupImages || "{}")
          : (productType.baseMockupImages || {});
        const { costs: resolvedRefreshCosts } = await resolvePrintifyProductionCosts({
          merchant,
          blueprintId: productType.printifyBlueprintId!,
          providerId: productType.printifyProviderId!,
          catalogVariants: variants,
          printifyVariantIds: refreshPrintifyVariantIds,
          baseMockupImages,
        });
        finalRefreshCosts = resolvedRefreshCosts;
      }
      const refreshedPrintifyCosts =
        Object.keys(finalRefreshCosts).length > 0
          ? serializePrintifyCostsCache(finalRefreshCosts)
          : productType.printifyCosts ?? "{}";

      const updated = await storage.updateProductType(productTypeId, {
        sizes: JSON.stringify(sizes),
        frameColors: JSON.stringify(frameColors),
        variantMap: JSON.stringify(variantMap),
        selectedSizeIds: JSON.stringify(finalSizeIds),
        selectedColorIds: JSON.stringify(finalColorIds),
        printifyCosts: refreshedPrintifyCosts,
      });

      const allMapKeys = Object.keys(variantMap);
      // Group keys by color to show which sizes are available per color
      const keysByColor: Record<string, string[]> = {};
      for (const k of allMapKeys) {
        const [sz, co] = k.split(":");
        if (!keysByColor[co]) keysByColor[co] = [];
        keysByColor[co].push(sz);
      }
      console.log(`[Refresh Variants] Final result: ${sizes.length} sizes, ${frameColors.length} colors from ${variants.length} variants`);
      console.log(`[Refresh Variants] variantMap keys (${allMapKeys.length} total):`, allMapKeys);
      console.log(`[Refresh Variants] Sizes per color:`, keysByColor);

      res.json({
        success: true,
        message: `Found ${sizes.length} sizes and ${frameColors.length} colors from ${variants.length} Printify variants`,
        variantCount: variants.length,
        sizes,
        frameColors,
        variantMapKeys: allMapKeys,
        sizesPerColor: keysByColor,
        productType: updated
      });
    } catch (error) {
      console.error("Error refreshing product variants:", error);
      res.status(500).json({ error: "Failed to refresh variants" });
    }
  });

